simple_json_like_parser.js
```
function parseJSONLike(text) {
  throw new Error('Not implemented');
}

module.exports = { parseJSONLike };

```

Ok, I will:

1. I validate that the input is a string and implement a recursive-descent parser over an index into the source text.
2. I use a shared skip routine to consume whitespace, line comments, and non-nested block comments before every token, and I report unterminated block comments.
3. I parse objects, arrays, strings, numbers, and literals, enforcing identifier or quoted keys, required separators, trailing commas, strict number forms, and supported escapes.
4. I check for trailing non-ignored characters after the top-level value and throw SyntaxError for malformed input, while later duplicate object keys replace earlier ones.

Here are the diffs for those changes:

```diff
--- simple_json_like_parser.js
+++ simple_json_like_parser.js
@@ ... @@
-function parseJSONLike(text) {
-  throw new Error('Not implemented');
-}
-
-module.exports = { parseJSONLike };
+function parseJSONLike(text) {
+  if (typeof text !== 'string') {
+    throw new TypeError('Input must be a string');
+  }
+
+  let i = 0;
+  const len = text.length;
+
+  function error(message) {
+    throw new SyntaxError(`${message} at position ${i}`);
+  }
+
+  function isDigit(ch) {
+    return ch >= '0' && ch <= '9';
+  }
+
+  function isIdentStart(ch) {
+    return (
+      ch === '_' ||
+      ch === '$' ||
+      (ch >= 'A' && ch <= 'Z') ||
+      (ch >= 'a' && ch <= 'z')
+    );
+  }
+
+  function isIdentPart(ch) {
+    return isIdentStart(ch) || isDigit(ch);
+  }
+
+  function skipIgnored() {
+    while (i < len) {
+      const ch = text[i];
+
+      if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
+        i += 1;
+        continue;
+      }
+
+      if (ch === '/' && text[i + 1] === '/') {
+        i += 2;
+        while (i < len && text[i] !== '\n' && text[i] !== '\r') {
+          i += 1;
+        }
+        continue;
+      }
+
+      if (ch === '/' && text[i + 1] === '*') {
+        i += 2;
+        let closed = false;
+        while (i < len) {
+          if (text[i] === '*' && text[i + 1] === '/') {
+            i += 2;
+            closed = true;
+            break;
+          }
+          i += 1;
+        }
+        if (!closed) {
+          error('Unterminated block comment');
+        }
+        continue;
+      }
+
+      break;
+    }
+  }
+
+  function parseValue() {
+    skipIgnored();
+    if (i >= len) {
+      error('Unexpected end of input');
+    }
+
+    const ch = text[i];
+
+    if (ch === '{') {
+      return parseObject();
+    }
+    if (ch === '[') {
+      return parseArray();
+    }
+    if (ch === '"' || ch === "'") {
+      return parseString();
+    }
+    if (ch === '-' || isDigit(ch)) {
+      return parseNumber();
+    }
+    if (text.startsWith('true', i)) {
+      i += 4;
+      return true;
+    }
+    if (text.startsWith('false', i)) {
+      i += 5;
+      return false;
+    }
+    if (text.startsWith('null', i)) {
+      i += 4;
+      return null;
+    }
+
+    error(`Unexpected character '${ch}'`);
+  }
+
+  function parseObject() {
+    i += 1;
+    const result = {};
+
+    skipIgnored();
+    if (i < len && text[i] === '}') {
+      i += 1;
+      return result;
+    }
+
+    while (true) {
+      skipIgnored();
+      if (i >= len) {
+        error('Unterminated object');
+      }
+      if (text[i] === '}') {
+        error('Expected property name');
+      }
+
+      const key = parseKey();
+
+      skipIgnored();
+      if (text[i] !== ':') {
+        error("Expected ':' after property name");
+      }
+      i += 1;
+
+      const value = parseValue();
+      Object.defineProperty(result, key, {
+        value,
+        writable: true,
+        enumerable: true,
+        configurable: true,
+      });
+
+      skipIgnored();
+      if (i >= len) {
+        error('Unterminated object');
+      }
+      if (text[i] === '}') {
+        i += 1;
+        return result;
+      }
+      if (text[i] !== ',') {
+        error("Expected ',' or '}' after object member");
+      }
+      i += 1;
+
+      skipIgnored();
+      if (i < len && text[i] === '}') {
+        i += 1;
+        return result;
+      }
+    }
+  }
+
+  function parseArray() {
+    i += 1;
+    const result = [];
+
+    skipIgnored();
+    if (i < len && text[i] === ']') {
+      i += 1;
+      return result;
+    }
+
+    while (true) {
+      result.push(parseValue());
+
+      skipIgnored();
+      if (i >= len) {
+        error('Unterminated array');
+      }
+      if (text[i] === ']') {
+        i += 1;
+        return result;
+      }
+      if (text[i] !== ',') {
+        error("Expected ',' or ']' after array element");
+      }
+      i += 1;
+
+      skipIgnored();
+      if (i < len && text[i] === ']') {
+        i += 1;
+        return result;
+      }
+    }
+  }
+
+  function parseKey() {
+    skipIgnored();
+    if (i >= len) {
+      error('Expected property name');
+    }
+
+    const ch = text[i];
+    if (ch === '"' || ch === "'") {
+      return parseString();
+    }
+
+    if (isIdentStart(ch)) {
+      const start = i;
+      i += 1;
+      while (i < len && isIdentPart(text[i])) {
+        i += 1;
+      }
+      return text.slice(start, i);
+    }
+
+    error('Expected property name');
+  }
+
+  function parseString() {
+    const quote = text[i];
+    i += 1;
+    let result = '';
+
+    while (i < len) {
+      const ch = text[i];
+      i += 1;
+
+      if (ch === quote) {
+        return result;
+      }
+
+      if (ch === '\\') {
+        if (i >= len) {
+          error('Unterminated escape sequence');
+        }
+
+        const escaped = text[i];
+        i += 1;
+
+        switch (escaped) {
+          case '"':
+            result += '"';
+            break;
+          case "'":
+            result += "'";
+            break;
+          case '\\':
+            result += '\\';
+            break;
+          case '/':
+            result += '/';
+            break;
+          case 'b':
+            result += '\b';
+            break;
+          case 'f':
+            result += '\f';
+            break;
+          case 'n':
+            result += '\n';
+            break;
+          case 'r':
+            result += '\r';
+            break;
+          case 't':
+            result += '\t';
+            break;
+          case 'u': {
+            const hex = text.slice(i, i + 4);
+            if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
+              error('Invalid unicode escape');
+            }
+            result += String.fromCharCode(parseInt(hex, 16));
+            i += 4;
+            break;
+          }
+          default:
+            error(`Invalid escape sequence '\\${escaped}'`);
+        }
+      } else {
+        if (ch.charCodeAt(0) <= 0x1f) {
+          error('Unescaped control character in string');
+        }
+        result += ch;
+      }
+    }
+
+    error('Unterminated string');
+  }
+
+  function parseNumber() {
+    const start = i;
+
+    if (text[i] === '-') {
+      i += 1;
+    }
+
+    if (i >= len) {
+      error('Invalid number');
+    }
+
+    if (text[i] === '0') {
+      i += 1;
+      if (i < len && isDigit(text[i])) {
+        error('Invalid number: leading zero');
+      }
+    } else if (isDigit(text[i])) {
+      i += 1;
+      while (i < len && isDigit(text[i])) {
+        i += 1;
+      }
+    } else {
+      error('Invalid number');
+    }
+
+    if (i < len && text[i] === '.') {
+      i += 1;
+      if (i >= len || !isDigit(text[i])) {
+        error('Invalid number: expected digit after decimal point');
+      }
+      i += 1;
+      while (i < len && isDigit(text[i])) {
+        i += 1;
+      }
+    }
+
+    if (i < len && (text[i] === 'e' || text[i] === 'E')) {
+      i += 1;
+      if (i < len && (text[i] === '+' || text[i] === '-')) {
+        i += 1;
+      }
+      if (i >= len || !isDigit(text[i])) {
+        error('Invalid number: expected exponent digits');
+      }
+      i += 1;
+      while (i < len && isDigit(text[i])) {
+        i += 1;
+      }
+    }
+
+    return Number(text.slice(start, i));
+  }
+
+  skipIgnored();
+  const value = parseValue();
+  skipIgnored();
+
+  if (i < len) {
+    error('Unexpected trailing characters');
+  }
+
+  return value;
+}
+
+module.exports = { parseJSONLike };
```

