+pub fn is_prime(n: u64) -> bool {
+    if n < 2 {
+        return false;
+    }
+    if n % 2 == 0 {
+        return n == 2;
+    }
+    if n % 3 == 0 {
+        return n == 3;
+    }
+
+    let mut candidate = 5u64;
+    while candidate <= n / candidate {
+        if n % candidate == 0 || n % (candidate + 2) == 0 {
+            return false;
+        }
+        candidate += 6;
+    }
+
+    true
+}
+
+pub fn prime_factors(mut n: u64) -> Vec<u64> {
+    let mut factors = Vec::new();
+
+    if n <= 1 {
+        return factors;
+    }
+
+    while n % 2 == 0 {
+        factors.push(2);
+        n /= 2;
+    }
+
+    let mut candidate = 3u64;
+    while candidate <= n / candidate {
+        while n % candidate == 0 {
+            factors.push(candidate);
+            n /= candidate;
+        }
+        candidate += 2;
+    }
+
+    if n > 1 {
+        factors.push(n);
+    }
+
+    factors
+}
+
+pub fn divisors(n: u64) -> Vec<u64> {
+    if n == 0 {
+        return Vec::new();
+    }
+
+    let factors = prime_factors(n);
+    let mut result = vec![1u64];
+    let mut index = 0;
+
+    while index < factors.len() {
+        let prime = factors[index];
+        let mut exponent = 0u32;
+
+        while index < factors.len() && factors[index] == prime {
+            exponent += 1;
+            index += 1;
+        }
+
+        let existing_len = result.len();
+        let mut power = 1u64;
+
+        for _ in 0..exponent {
+            power *= prime;
+            for j in 0..existing_len {
+                let value = result[j] * power;
+                result.push(value);
+            }
+        }
+    }
+
+    result.sort_unstable();
+    result
+}
+
+pub fn totient(n: u64) -> u64 {
+    if n == 0 {
+        return 0;
+    }
+
+    let factors = prime_factors(n);
+    let mut result = n;
+    let mut last_factor = 0u64;
+
+    for factor in factors {
+        if factor != last_factor {
+            result = result / factor * (factor - 1);
+            last_factor = factor;
+        }
+    }
+
+    result
+}
