+package bankaccount
+
+import (
+	"errors"
+	"sync"
+)
+
+const (
+	KindOpen        = "open"
+	KindDeposit     = "deposit"
+	KindWithdraw    = "withdraw"
+	KindTransferIn  = "transfer_in"
+	KindTransferOut = "transfer_out"
+	KindClose       = "close"
+)
+
+var (
+	ErrAccountNotFound   = errors.New("account not found")
+	ErrAccountClosed     = errors.New("account closed")
+	ErrInvalidAmount     = errors.New("amount must be positive")
+	ErrInsufficientFunds = errors.New("insufficient funds")
+	ErrNonZeroBalance    = errors.New("account balance must be zero")
+	ErrSameAccount       = errors.New("cannot transfer to the same account")
+	ErrInvalidOpening    = errors.New("invalid opening parameters")
+)
+
+type Entry struct {
+	Kind    string
+	Amount  int64
+	Balance int64
+}
+
+type account struct {
+	balance        int64
+	overdraftLimit int64
+	closed         bool
+	history        []Entry
+}
+
+type Bank struct {
+	mu       sync.Mutex
+	nextID   int
+	accounts map[int]*account
+}
+
+func NewBank() *Bank {
+	return &Bank{accounts: make(map[int]*account)}
+}
+
+func (b *Bank) Open(initialBalance, overdraftLimit int64) (int, error) {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	if initialBalance < 0 || overdraftLimit < 0 {
+		return 0, ErrInvalidOpening
+	}
+	if b.accounts == nil {
+		b.accounts = make(map[int]*account)
+	}
+
+	b.nextID++
+	id := b.nextID
+	b.accounts[id] = &account{
+		balance:        initialBalance,
+		overdraftLimit: overdraftLimit,
+		history: []Entry{{
+			Kind:    KindOpen,
+			Amount:  initialBalance,
+			Balance: initialBalance,
+		}},
+	}
+	return id, nil
+}
+
+func (b *Bank) Deposit(id int, amount int64) error {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	a, ok := b.accounts[id]
+	if !ok {
+		return ErrAccountNotFound
+	}
+	if a.closed {
+		return ErrAccountClosed
+	}
+	if amount <= 0 {
+		return ErrInvalidAmount
+	}
+
+	a.balance += amount
+	a.history = append(a.history, Entry{
+		Kind:    KindDeposit,
+		Amount:  amount,
+		Balance: a.balance,
+	})
+	return nil
+}
+
+func (b *Bank) Withdraw(id int, amount int64) error {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	a, ok := b.accounts[id]
+	if !ok {
+		return ErrAccountNotFound
+	}
+	if a.closed {
+		return ErrAccountClosed
+	}
+	if amount <= 0 {
+		return ErrInvalidAmount
+	}
+	if amount > a.balance+a.overdraftLimit {
+		return ErrInsufficientFunds
+	}
+
+	a.balance -= amount
+	a.history = append(a.history, Entry{
+		Kind:    KindWithdraw,
+		Amount:  -amount,
+		Balance: a.balance,
+	})
+	return nil
+}
+
+func (b *Bank) Transfer(fromID, toID int, amount int64) error {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	if amount <= 0 {
+		return ErrInvalidAmount
+	}
+	if fromID == toID {
+		return ErrSameAccount
+	}
+
+	from, ok := b.accounts[fromID]
+	if !ok {
+		return ErrAccountNotFound
+	}
+	if from.closed {
+		return ErrAccountClosed
+	}
+
+	to, ok := b.accounts[toID]
+	if !ok {
+		return ErrAccountNotFound
+	}
+	if to.closed {
+		return ErrAccountClosed
+	}
+
+	if amount > from.balance+from.overdraftLimit {
+		return ErrInsufficientFunds
+	}
+
+	from.balance -= amount
+	to.balance += amount
+	from.history = append(from.history, Entry{
+		Kind:    KindTransferOut,
+		Amount:  -amount,
+		Balance: from.balance,
+	})
+	to.history = append(to.history, Entry{
+		Kind:    KindTransferIn,
+		Amount:  amount,
+		Balance: to.balance,
+	})
+	return nil
+}
+
+func (b *Bank) Balance(id int) (int64, error) {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	a, ok := b.accounts[id]
+	if !ok {
+		return 0, ErrAccountNotFound
+	}
+	return a.balance, nil
+}
+
+func (b *Bank) History(id int) ([]Entry, error) {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	a, ok := b.accounts[id]
+	if !ok {
+		return nil, ErrAccountNotFound
+	}
+
+	out := make([]Entry, len(a.history))
+	copy(out, a.history)
+	return out, nil
+}
+
+func (b *Bank) Close(id int) error {
+	b.mu.Lock()
+	defer b.mu.Unlock()
+
+	a, ok := b.accounts[id]
+	if !ok {
+		return ErrAccountNotFound
+	}
+	if a.closed {
+		return ErrAccountClosed
+	}
+	if a.balance != 0 {
+		return ErrNonZeroBalance
+	}
+
+	a.closed = true
+	a.history = append(a.history, Entry{
+		Kind:    KindClose,
+		Amount:  0,
+		Balance: 0,
+	})
+	return nil
+}
