+pub fn compare_versions(left: &str, right: &str) -> Ordering {
+    let mut left_segments = left.split('.');
+    let mut right_segments = right.split('.');
+
+    loop {
+        let left_segment = left_segments.next();
+        let right_segment = right_segments.next();
