+function calculateCheckDigit(digits) {
+  if (typeof digits !== 'string' || !/^\d{7}$/.test(digits)) {
+    throw new Error('digits must be exactly seven digits');
+  }
+
+  const weights = [3, 1, 3, 1, 3, 1, 3];
+  let sum = 0;
+
+  for (let i = 0; i < 7; i += 1) {
