+#[derive(Debug, Default, PartialEq, Eq)]
+pub struct DependencyGraph {
+    dependencies: HashMap<String, BTreeSet<String>>,
+}
+
+#[derive(Debug, PartialEq, Eq)]
+pub enum ResolveError {
+    Cycle,
+}
+
+impl DependencyGraph {
+    pub fn new() -> Self {
+        Self {
+            dependencies: HashMap::new(),
+        }
+    }
+
+    pub fn add_package(&mut self, package: &str) {
+        self.dependencies.entry(package.to_string()).or_default();
+    }
+
+    pub fn add_dependency(&mut self, package: &str, dependency: &str) {
+        self.dependencies
+            .entry(package.to_string())
+            .or_default()
+            .insert(dependency.to_string());
+        self.dependencies
+            .entry(dependency.to_string())
+            .or_default();
+    }
+
+    pub fn resolve(&self) -> Result<Vec<String>, ResolveError> {
+        let mut remaining: BTreeSet<String> = self.dependencies.keys().cloned().collect();
+        let mut resolved = Vec::with_capacity(remaining.len());
+
+        while !remaining.is_empty() {
+            let mut next: Option<String> = None;
+
+            for package in &remaining {
+                let dependencies = self.dependencies.get(package).unwrap();
+                if dependencies.iter().all(|dependency| !remaining.contains(dependency)) {
+                    next = Some(package.clone());
+                    break;
+                }
+            }
+
+            match next {
+                Some(package) => {
+                    remaining.remove(&package);
+                    resolved.push(package);
+                }
+                None => return Err(ResolveError::Cycle),
+            }
+        }
+
+        Ok(resolved)
+    }
