+        return static_cast<char>(c - 'A' + 'a');
+    }
+    return static_cast<char>(c);
+}
+
+} // namespace
+
+std::map<std::string, std::size_t> count_words(const std::string& text) {
+    std::map<std::string, std::size_t> counts;
+    std::string current;
+    const std::size_t n = text.size();
+
+    auto flush = [&]() {
+        if (!current.empty()) {
+            ++counts[current];
+            current.clear();
+        }
+    };
+
+    for (std::size_t i = 0; i < n; ++i) {
+        const unsigned char c = static_cast<unsigned char>(text[i]);
+
+        if (is_word_char(c)) {
+            current.push_back(to_lower_ascii(c));
+        } else if (c == '\'') {
+            const bool has_previous_word_char = !current.empty();
+            const bool has_next_word_char =
+                (i + 1 < n) && is_word_char(static_cast<unsigned char>(text[i + 1]));
+
+            if (has_previous_word_char && has_next_word_char) {
+                current.push_back('\'');
+            } else {
+                flush();
+            }
+        } else {
+            flush();
+        }
+    }
+
+    flush();
+    return counts;
+}
+
+} // namespace word_count
