+template <typename T>
+class RingBuffer {
+public:
+    explicit RingBuffer(std::size_t capacity)
+        : data_(capacity), head_(0), count_(0) {
+        if (capacity == 0) {
+            throw std::invalid_argument("RingBuffer capacity must be greater than zero");
+        }
+    }
+
+    void write(const T& value) {
+        if (full()) {
+            throw std::overflow_error("RingBuffer is full");
+        }
+        data_[(head_ + count_) % data_.size()] = value;
+        ++count_;
+    }
+
+    T read() {
+        if (empty()) {
+            throw std::underflow_error("RingBuffer is empty");
+        }
+        T value = data_[head_];
+        head_ = (head_ + 1) % data_.size();
+        --count_;
+        return value;
+    }
+
+    void overwrite(const T& value) {
+        if (full()) {
+            data_[head_] = value;
+            head_ = (head_ + 1) % data_.size();
+        } else {
+            write(value);
+        }
+    }
+
+    void clear() {
+        head_ = 0;
+        count_ = 0;
+    }
+
+    bool empty() const { return count_ == 0; }
+
+    bool full() const { return count_ == data_.size(); }
+
+    std::size_t size() const { return count_; }
+
+    std::size_t capacity() const { return data_.size(); }
