+    private long compute(int n) {
+        Long cached = cache.get(n);
+        if (cached != null) {
+            return cached;
+        }
+
+        long value;
+        if (n == 0) {
+            value = 0L;
+        } else if (n == 1) {
+            value = 1L;
+        } else {
+            value = compute(n - 1) + compute(n - 2);
+        }
+
+        cache.put(n, value);
+        computationCount++;
+        return value;
+    }
+
