+import java.util.HashMap;
+import java.util.Locale;
+import java.util.Map;
+
+public class WordTally {
+    public Map<String, Integer> countWords(String text) {
+        Map<String, Integer> counts = new HashMap<>();
+        int[] codePoints = text.codePoints().toArray();
+        StringBuilder current = new StringBuilder();
+
+        for (int i = 0; i < codePoints.length; i++) {
+            int cp = codePoints[i];
+
+            if (Character.isLetterOrDigit(cp)) {
+                current.appendCodePoint(cp);
+            } else if (cp == '\'') {
+                boolean internalApostrophe = current.length() > 0
+                        && i + 1 < codePoints.length
+                        && Character.isLetterOrDigit(codePoints[i + 1]);
+
+                if (internalApostrophe) {
+                    current.append('\'');
+                } else {
+                    addWord(counts, current);
+                }
+            } else {
+                addWord(counts, current);
+            }
+        }
+
+        addWord(counts, current);
+        return counts;
+    }
+
+    private void addWord(Map<String, Integer> counts, StringBuilder current) {
+        if (current.length() == 0) {
+            return;
+        }
+
+        String word = current.toString().toLowerCase(Locale.ROOT);
+        counts.merge(word, 1, Integer::sum);
+        current.setLength(0);
+    }
