+function generateIPAddresses(s) {
+  if (typeof s !== 'string') return [];
+  if (!/^\d*$/.test(s)) return [];
+  const n = s.length;
+  if (n < 4 || n > 12) return [];
+  const result = [];
+  const parts = [];
+
+  function backtrack(start, partCount) {
+    if (partCount === 4) {
+      if (start === n) {
+        result.push(parts.join('.'));
+      }
+      return;
+    }
+    const remainingParts = 4 - partCount;
+    const remainingChars = n - start;
+    if (remainingChars < remainingParts || remainingChars > remainingParts * 3) {
+      return;
+    }
+    for (let len = 1; len <= 3; len++) {
+      if (start + len > n) break;
+      const part = s.slice(start, start + len);
+      if (part.length > 1 && part[0] === '0') continue;
+      const num = Number(part);
+      if (num > 255) continue;
+      parts.push(part);
+      backtrack(start + len, partCount + 1);
+      parts.pop();
+    }
+  }
+
+  backtrack(0, 0);
+  return [...new Set(result)].sort();
+}
+
+module.exports = { generateIPAddresses };
