+    skip_whitespace(text, index);
+
+    if (index < text.size()) {
+        throw std::invalid_argument("unexpected closing bracket");
+    }
+
+    return program;
+}
+
+void Robot::parse_program_impl(
+    const std::string& text,
+    std::size_t& index,
+    bool in_repeat,
+    std::vector<Command>& out
+) {
+    while (true) {
+        skip_whitespace(text, index);
+
+        if (index >= text.size()) {
+            break;
+        }
+
+        char token = text[index];
+
+        if (token == ']') {
+            if (in_repeat) {
+                break;
+            }
+
+            throw std::invalid_argument("unexpected closing bracket");
+        }
+
+        if (token == 'L') {
+            ++index;
+            Command command;
+            command.type = Command::Type::TurnLeft;
+            out.push_back(command);
+        } else if (token == 'R') {
+            ++index;
+            Command command;
+            command.type = Command::Type::TurnRight;
+            out.push_back(command);
+        } else if (token == 'F') {
+            ++index;
+            Command command;
+            command.type = Command::Type::MoveForward;
+            out.push_back(command);
+        } else if (token == 'B') {
+            ++index;
+            Command command;
+            command.type = Command::Type::MoveBackward;
+            out.push_back(command);
+        } else if (std::isdigit(static_cast<unsigned char>(token))) {
+            int count = parse_count(text, index);
+
+            skip_whitespace(text, index);
+
+            if (index >= text.size() || text[index] != '[') {
+                throw std::invalid_argument("expected opening bracket");
+            }
+
+            ++index;
+
+            Command command;
+            command.type = Command::Type::Repeat;
+            command.count = count;
+
+            parse_program_impl(text, index, true, command.body);
+
+            if (index >= text.size() || text[index] != ']') {
+                throw std::invalid_argument("unmatched opening bracket");
+            }
+
+            ++index;
+            out.push_back(command);
+        } else if (token == '[') {
+            ++index;
+
+            Command command;
+            command.type = Command::Type::Repeat;
+            command.count = 1;
+
+            parse_program_impl(text, index, true, command.body);
+
+            if (index >= text.size() || text[index] != ']') {
+                throw std::invalid_argument("unmatched opening bracket");
+            }
+
+            ++index;
+            out.push_back(command);
+        } else {
+            throw std::invalid_argument("unknown command");
+        }
+    }
+}
+
+int Robot::parse_count(const std::string& text, std::size_t& index) {
+    long long value = 0;
+    bool found_digit = false;
+
+    while (
+        index < text.size() &&
+        std::isdigit(static_cast<unsigned char>(text[index]))
+    ) {
+        found_digit = true;
+        value = value * 10 + (text[index] - '0');
+
+        if (value > INT_MAX) {
+            throw std::invalid_argument("repeat count is too large");
+        }
+
+        ++index;
+    }
+
+    if (!found_digit || value <= 0) {
+        throw std::invalid_argument("invalid repeat count");
+    }
+
+    return static_cast<int>(value);
+}
+
+void Robot::skip_whitespace(const std::string& text, std::size_t& index) {
+    while (
+        index < text.size() &&
+        std::isspace(static_cast<unsigned char>(text[index]))
+    ) {
+        ++index;
+    }
+}
