+func Chunk(items []int, size int) [][]int {
+	if size <= 0 {
+		return nil
+	}
+
+	chunks := make([][]int, 0, (len(items)+size-1)/size)
+	for start := 0; start < len(items); start += size {
+		end := start + size
+		if end > len(items) {
+			end = len(items)
+		}
+
+		chunk := make([]int, end-start)
+		copy(chunk, items[start:end])
+		chunks = append(chunks, chunk)
+	}
+
+	return chunks
+}
+
+func Window(items []int, size int) [][]int {
+	if size <= 0 || size > len(items) {
+		return [][]int{}
+	}
+
+	windows := make([][]int, 0, len(items)-size+1)
+	for start := 0; start+size <= len(items); start++ {
+		window := make([]int, size)
+		copy(window, items[start:start+size])
+		windows = append(windows, window)
+	}
+
+	return windows
+}
+
+func Rotate(items []int, steps int) []int {
+	n := len(items)
+	if n == 0 {
+		return []int{}
+	}
+
+	steps %= n
+	if steps < 0 {
+		steps += n
+	}
+
+	rotated := make([]int, 0, n)
+	rotated = append(rotated, items[steps:]...)
+	rotated = append(rotated, items[:steps]...)
+
+	return rotated
+}
+
+func Flatten(groups [][]int) []int {
+	total := 0
+	for _, group := range groups {
+		total += len(group)
+	}
+
+	flat := make([]int, 0, total)
+	for _, group := range groups {
+		flat = append(flat, group...)
+	}
+
+	return flat
