+func normalize(text string) []rune {
+	text = strings.ToLower(text)
+	normalized := make([]rune, 0, len(text))
+	for _, r := range text {
+		if unicode.IsLetter(r) || unicode.IsDigit(r) {
+			normalized = append(normalized, r)
+		}
+	}
+	return normalized
+}
+
+// IsPalindrome reports whether text is a palindrome after normalization.
+func IsPalindrome(text string) bool {
+	normalized := normalize(text)
+	for left, right := 0, len(normalized)-1; left < right; left, right = left+1, right-1 {
+		if normalized[left] != normalized[right] {
+			return false
+		}
+	}
+	return true
+}
+
+// AreAnagrams reports whether first and second are anagrams after normalization.
+func AreAnagrams(first, second string) bool {
+	firstNormalized := normalize(first)
+	secondNormalized := normalize(second)
+
+	if len(firstNormalized) != len(secondNormalized) {
+		return false
+	}
+
+	counts := make(map[rune]int)
+	for _, r := range firstNormalized {
+		counts[r]++
+	}
+
+	for _, r := range secondNormalized {
+		counts[r]--
+		if counts[r] < 0 {
+			return false
+		}
+	}
+
+	return true
+}
