+                    }
+                }
+                let mut has_exp_digit = false;
+                while let Some(c) = self.peek() {
+                    if c.is_ascii_digit() {
+                        has_exp_digit = true;
+                        self.pos += 1;
+                    } else {
+                        break;
+                    }
+                }
+                if !has_exp_digit {
+                    return Err(ParseError::InvalidNumber);
+                }
+            }
+        }
