+public class HammingCodec {
+
+    public static byte encode(int nibble) {
+        if (nibble < 0 || nibble > 0xF) {
+            throw new IllegalArgumentException("Nibble out of range: " + nibble);
+        }
+
+        int d0 = (nibble >> 0) & 1;
+        int d1 = (nibble >> 1) & 1;
+        int d2 = (nibble >> 2) & 1;
+        int d3 = (nibble >> 3) & 1;
+
+        int p1 = d0 ^ d1 ^ d3;
+        int p2 = d0 ^ d2 ^ d3;
+        int p4 = d1 ^ d2 ^ d3;
+        int p8 = p1 ^ p2 ^ p4 ^ d0 ^ d1 ^ d2 ^ d3;
+
+        int code = (p1 << 0)
+                | (p2 << 1)
+                | (d0 << 2)
+                | (p4 << 3)
+                | (d1 << 4)
+                | (d2 << 5)
+                | (d3 << 6)
+                | (p8 << 7);
+        return (byte) code;
+    }
+
+    public static int errorPosition(byte codeword) {
+        int code = codeword & 0xFF;
+        int syndrome = syndrome(code);
+        int parity = overallParity(code);
+
+        if (syndrome == 0 && parity == 0) {
+            return 0;
+        }
+        if (syndrome == 0) {
+            return 8;
+        }
+        if (parity == 1) {
+            return syndrome;
+        }
+        return -1;
+    }
+
+    public static byte repair(byte codeword) {
+        int position = errorPosition(codeword);
+        if (position < 0) {
+            throw new IllegalArgumentException("Uncorrectable codeword: " + (codeword & 0xFF));
+        }
+        int code = codeword & 0xFF;
+        if (position > 0) {
+            code ^= 1 << (position - 1);
+        }
+        return (byte) code;
+    }
+
+    public static int decode(byte codeword) {
+        int code = repair(codeword) & 0xFF;
+        return bit(code, 3)
+                | (bit(code, 5) << 1)
+                | (bit(code, 6) << 2)
+                | (bit(code, 7) << 3);
+    }
+
+    private static int bit(int code, int position) {
+        return (code >> (position - 1)) & 1;
+    }
+
+    private static int syndrome(int code) {
+        int a = bit(code, 1) ^ bit(code, 3) ^ bit(code, 5) ^ bit(code, 7);
+        int b = bit(code, 2) ^ bit(code, 3) ^ bit(code, 6) ^ bit(code, 7);
+        int c = bit(code, 4) ^ bit(code, 5) ^ bit(code, 6) ^ bit(code, 7);
+        return a | (b << 1) | (c << 2);
+    }
+
+    private static int overallParity(int code) {
+        int parity = 0;
+        for (int position = 1; position <= 8; position++) {
+            parity ^= bit(code, position);
+        }
+        return parity;
+    }
