+
+impl Fraction {
+    pub fn new(numerator: i64, denominator: i64) -> Self {
+        assert!(denominator != 0, "denominator must not be zero");
+
+        let mut num = numerator as i128;
+        let mut den = denominator as i128;
+        if den < 0 {
+            num = -num;
+            den = -den;
+        }
+
+        let divisor = gcd(num.abs(), den);
+        num /= divisor;
+        den /= divisor;
