+        let scale = power_of_ten(decimal_places);
+        let scaled = self.scaled_rounded(decimal_places);
+        assert!(
+            scaled >= i64::MIN as i128 && scaled <= i64::MAX as i128,
+            "rounded numerator does not fit in an i64"
+        );
+        Fraction::new(scaled as i64, scale as i64)
+    }
+
+    pub fn to_decimal_string(&self, decimal_places: u32) -> String {
+        let scale = power_of_ten(decimal_places);
+        let scaled = self.scaled_rounded(decimal_places);
+
+        let sign = if scaled < 0 { "-" } else { "" };
+        let magnitude = scaled.abs();
+        let integer_part = magnitude / scale;
+        let fractional_part = magnitude % scale;
+
+        if decimal_places == 0 {
+            format!("{}{}", sign, integer_part)
+        } else {
+            format!(
+                "{}{}.{:0width$}",
+                sign,
+                integer_part,
+                fractional_part,
+                width = decimal_places as usize
+            )
+        }
+    }
