+    /// rounded to the nearest integer with ties going away from zero.
+    fn scaled_rounded(&self, decimal_places: u32) -> i128 {
+        let scale = power_of_ten(decimal_places);
+        let value = self.numerator as i128 * scale;
+        let denominator = self.denominator as i128;
+
+        let quotient = value / denominator;
+        let remainder = value % denominator;
+
+        let bump = if remainder.abs() * 2 >= denominator {
+            remainder.signum()
+        } else {
