+import "fmt"
+
+func KthSmallest(nums []int, k int) (int, error) {
+	if k < 1 || k > len(nums) {
+		return 0, fmt.Errorf("k=%d is out of range for slice of length %d", k, len(nums))
+	}
+	arr := make([]int, len(nums))
+	copy(arr, nums)
+	return quickSelect(arr, k-1), nil
