+
+func Median(nums []int) (float64, error) {
+	n := len(nums)
+	if n == 0 {
+		return 0, fmt.Errorf("median of empty slice")
+	}
+	arr := make([]int, n)
+	copy(arr, nums)
+	if n%2 == 1 {
+		return float64(quickSelect(arr, n/2)), nil
+	}
+	left := quickSelect(arr, n/2-1)
+	right := quickSelect(arr, n/2)
+	return float64(left+right) / 2, nil
+}
+
+func quickSelect(arr []int, k int) int {
+	lo, hi := 0, len(arr)-1
+	for lo <= hi {
+		if lo == hi {
+			return arr[lo]
+		}
+		pivot := arr[lo+(hi-lo)/2]
+		lt, i, gt := lo, lo, hi
+		for i <= gt {
+			switch {
+			case arr[i] < pivot:
+				arr[lt], arr[i] = arr[i], arr[lt]
+				lt++
+				i++
+			case arr[i] > pivot:
+				arr[i], arr[gt] = arr[gt], arr[i]
+				gt--
+			default:
+				i++
+			}
+		}
+		if k < lt {
+			hi = lt - 1
+		} else if k > gt {
+			lo = gt + 1
+		} else {
+			return arr[k]
+		}
+	}
+	return arr[k]
+}
+
+func SearchRotated(nums []int, target int) int {
+	lo, hi := 0, len(nums)-1
+	for lo <= hi {
+		mid := lo + (hi-lo)/2
+		if nums[mid] == target {
+			return mid
+		}
+		if nums[lo] < nums[mid] {
+			if nums[lo] <= target && target < nums[mid] {
+				hi = mid - 1
+			} else {
+				lo = mid + 1
+			}
+		} else if nums[lo] > nums[mid] {
+			if nums[mid] < target && target <= nums[hi] {
+				lo = mid + 1
+			} else {
+				hi = mid - 1
+			}
+		} else {
+			lo++
+		}
+	}
+	return -1
