+#include <cstddef>
+#include <set>
+#include <stdexcept>
+#include <tuple>
+#include <unordered_map>
+
+class PriorityQueue {
+public:
+    void push(int value, int priority);
+    int pop();
+    int peek() const;
+    bool empty() const;
+    std::size_t size() const;
+    void update_priority(int value, int new_priority);
+
+private:
+    using Entry = std::tuple<int, std::size_t, int>; // (priority, order, value)
+    std::set<Entry> entries_;
+    std::unordered_map<int, std::set<Entry>::iterator> index_;
+    std::size_t next_order_ = 0;
+};
+
+void PriorityQueue::push(int value, int priority) {
+    if (index_.find(value) != index_.end()) {
+        throw std::invalid_argument("value already exists");
+    }
+    auto it = entries_.insert({priority, next_order_++, value}).first;
+    index_[value] = it;
+}
+
+int PriorityQueue::pop() {
+    if (entries_.empty()) {
+        throw std::out_of_range("priority queue is empty");
+    }
+    auto it = entries_.begin();
+    int value = std::get<2>(*it);
+    entries_.erase(it);
+    index_.erase(value);
+    return value;
+}
+
+int PriorityQueue::peek() const {
+    if (entries_.empty()) {
+        throw std::out_of_range("priority queue is empty");
+    }
+    return std::get<2>(*entries_.begin());
+}
+
+bool PriorityQueue::empty() const {
+    return entries_.empty();
+}
+
+std::size_t PriorityQueue::size() const {
+    return entries_.size();
+}
+
+void PriorityQueue::update_priority(int value, int new_priority) {
+    auto map_it = index_.find(value);
+    if (map_it == index_.end()) {
+        throw std::invalid_argument("value not found");
+    }
+    auto set_it = map_it->second;
+    int old_priority = std::get<0>(*set_it);
+    if (old_priority == new_priority) {
+        return;
+    }
+    std::size_t order = std::get<1>(*set_it);
+    entries_.erase(set_it);
+    auto new_it = entries_.insert({new_priority, order, value}).first;
+    map_it->second = new_it;
+}
