+
+func Merge(intervals []Interval) ([]Interval, error) {
+	for _, interval := range intervals {
+		if interval.Start >= interval.End {
+			return nil, errors.New("invalid interval: start must be before end")
+		}
+	}
+
+	if len(intervals) == 0 {
+		return []Interval{}, nil
+	}
+
+	sorted := make([]Interval, len(intervals))
+	copy(sorted, intervals)
+	sort.Slice(sorted, func(i, j int) bool {
+		if sorted[i].Start == sorted[j].Start {
+			return sorted[i].End < sorted[j].End
+		}
+		return sorted[i].Start < sorted[j].Start
+	})
+
+	merged := make([]Interval, 0, len(sorted))
+	merged = append(merged, sorted[0])
+
+	for _, interval := range sorted[1:] {
+		last := &merged[len(merged)-1]
+		if interval.Start <= last.End {
+			if interval.End > last.End {
+				last.End = interval.End
+			}
+		} else {
+			merged = append(merged, interval)
+		}
+	}
+
+	return merged, nil
+}
+
+func FreeSlots(window Interval, busy []Interval, minDuration int) ([]Interval, error) {
+	if window.Start >= window.End {
+		return nil, errors.New("invalid window: start must be before end")
+	}
+	if minDuration <= 0 {
+		return nil, errors.New("minDuration must be positive")
+	}
+
+	merged, err := Merge(busy)
+	if err != nil {
+		return nil, err
+	}
+
+	free := make([]Interval, 0)
+	cursor := window.Start
+
+	for _, interval := range merged {
+		if interval.End <= window.Start {
+			continue
+		}
+		if interval.Start >= window.End {
+			break
+		}
+
+		start := interval.Start
+		if start < window.Start {
+			start = window.Start
+		}
+
+		end := interval.End
+		if end > window.End {
+			end = window.End
+		}
+
+		if start > cursor {
+			gap := Interval{Start: cursor, End: start}
+			if gap.End-gap.Start >= minDuration {
+				free = append(free, gap)
+			}
+		}
+
+		if end > cursor {
+			cursor = end
+		}
+		if cursor >= window.End {
+			break
+		}
+	}
+
+	if cursor < window.End {
+		gap := Interval{Start: cursor, End: window.End}
+		if gap.End-gap.Start >= minDuration {
+			free = append(free, gap)
+		}
+	}
+
+	return free, nil
+}
+
+func Schedule(window Interval, busy []Interval, durations []int) ([]Interval, error) {
+	if window.Start >= window.End {
+		return nil, errors.New("invalid window: start must be before end")
+	}
+	if _, err := Merge(busy); err != nil {
+		return nil, err
+	}
+	for _, duration := range durations {
+		if duration <= 0 {
+			return nil, errors.New("duration must be positive")
+		}
+	}
+
+	scheduled := make([]Interval, 0, len(durations))
+	currentBusy := make([]Interval, len(busy))
+	copy(currentBusy, busy)
+
+	for _, duration := range durations {
+		free, err := FreeSlots(window, currentBusy, duration)
+		if err != nil {
+			return nil, err
+		}
+		if len(free) == 0 {
+			return nil, errors.New("cannot schedule all durations")
+		}
+
+		slot := Interval{Start: free[0].Start, End: free[0].Start + duration}
+		scheduled = append(scheduled, slot)
+		currentBusy = append(currentBusy, slot)
+	}
+
+	return scheduled, nil
+}
+
+func NewScheduler(busy []Interval) (*Scheduler, error) {
+	merged, err := Merge(busy)
+	if err != nil {
+		return nil, err
+	}
+	return &Scheduler{busy: merged}, nil
+}
+
+func (s *Scheduler) AddBusy(interval Interval) error {
+	if s == nil {
+		return errors.New("nil scheduler")
+	}
+	if interval.Start >= interval.End {
+		return errors.New("invalid interval: start must be before end")
+	}
+
+	updated := make([]Interval, 0, len(s.busy)+1)
+	updated = append(updated, s.busy...)
+	updated = append(updated, interval)
+
+	merged, err := Merge(updated)
+	if err != nil {
+		return err
+	}
+
+	s.busy = merged
+	return nil
+}
+
+func (s *Scheduler) Busy() []Interval {
+	if s == nil {
+		return []Interval{}
+	}
+	busy := make([]Interval, len(s.busy))
+	copy(busy, s.busy)
+	return busy
+}
+
+func (s *Scheduler) FreeSlots(window Interval, minDuration int) ([]Interval, error) {
+	if s == nil {
+		return nil, errors.New("nil scheduler")
+	}
+	return FreeSlots(window, s.busy, minDuration)
+}
+
+func (s *Scheduler) Schedule(window Interval, durations []int) ([]Interval, error) {
+	if s == nil {
+		return nil, errors.New("nil scheduler")
+	}
+
+	scheduled, err := Schedule(window, s.busy, durations)
+	if err != nil {
+		return nil, err
+	}
+
+	updated := make([]Interval, 0, len(s.busy)+len(scheduled))
+	updated = append(updated, s.busy...)
+	updated = append(updated, scheduled...)
+
+	merged, err := Merge(updated)
+	if err != nil {
+		return nil, err
+	}
+
+	s.busy = merged
+	return scheduled, nil
