+namespace {
+
+// Copies the digits of input into cleaned, returning false as soon as a
+// character that is neither a digit, a space, nor a hyphen is found.
+bool clean(const std::string& input, std::string& cleaned) {
+    for (char c : input) {
+        if (c == ' ' || c == '-') {
+            continue;
+        }
+        if (c < '0' || c > '9') {
+            return false;
+        }
+        cleaned.push_back(c);
+    }
+    return true;
+}
+
+// Weighted sum of the digits, weights 2,3,4,5,6,7,2,3,... from the right,
+// reduced modulo 11.
+int remainder_of(const std::string& digits) {
+    int sum = 0;
+    int weight = 2;
+    for (auto it = digits.rbegin(); it != digits.rend(); ++it) {
+        sum += (*it - '0') * weight;
+        weight = (weight == 7) ? 2 : weight + 1;
+    }
+    return sum % 11;
+}
+
+}  // namespace
+
+bool is_valid(const std::string& code) {
+    std::string digits;
+    if (!clean(code, digits)) {
+        return false;
+    }
+    if (digits.size() < 2) {
+        return false;
+    }
+
+    const std::string payload = digits.substr(0, digits.size() - 1);
+    const int check = digits.back() - '0';
+    const int remainder = remainder_of(payload);
+
+    if (remainder == 0) {
+        return check == 0;
+    }
+    if (remainder == 1) {
+        return false;
+    }
+    return check == 11 - remainder;
+}
+
+std::optional<int> check_digit(const std::string& payload) {
+    std::string digits;
+    if (!clean(payload, digits)) {
+        return std::nullopt;
+    }
+    if (digits.empty()) {
+        return std::nullopt;
+    }
+
+    const int remainder = remainder_of(digits);
+    if (remainder == 1) {
+        return std::nullopt;
+    }
+    if (remainder == 0) {
+        return 0;
+    }
+    return 11 - remainder;
+}
