+    public List<String> mostCommonWords(String text, int limit) {
+        if (limit <= 0) {
+            return new ArrayList<>();
+        }
+
+        Map<String, Integer> counts = countWords(text);
+        List<String> words = new ArrayList<>(counts.keySet());
+        words.sort((left, right) -> {
+            int byCount = Integer.compare(counts.get(right), counts.get(left));
+            if (byCount != 0) {
+                return byCount;
+            }
+            return left.compareTo(right);
+        });
+
+        if (words.size() > limit) {
+            return new ArrayList<>(words.subList(0, limit));
+        }
+        return words;
+    }
+
+    public Map<Integer, Integer> countByFrequency(String text) {
+        Map<String, Integer> wordCounts = countWords(text);
+        Map<Integer, Integer> distribution = new HashMap<>();
+        for (int count : wordCounts.values()) {
+            distribution.merge(count, 1, Integer::sum);
+        }
+        return distribution;
+    }
+
+    private List<String> extractWords(String text) {
+        List<String> words = new ArrayList<>();
+        if (text == null) {
+            return words;
+        }
+
+        StringBuilder current = new StringBuilder();
+        for (int i = 0; i < text.length(); ) {
+            int codePoint = text.codePointAt(i);
+            if (Character.isLetter(codePoint)) {
+                current.appendCodePoint(codePoint);
+            } else if (current.length() > 0) {
+                words.add(current.toString().toLowerCase(Locale.ROOT));
+                current.setLength(0);
+            }
+            i += Character.charCount(codePoint);
+        }
+
+        if (current.length() > 0) {
+            words.add(current.toString().toLowerCase(Locale.ROOT));
+        }
+        return words;
+    }
