+public class SlidingWindow {
+    public List<Integer> windowSums(List<Integer> numbers, int size) {
+        if (size <= 0) {
+            throw new IllegalArgumentException("Window size must be positive");
+        }
+
+        List<Integer> sums = new ArrayList<>();
+
+        if (numbers.size() < size) {
+            return sums;
+        }
+
+        int windowSum = 0;
+        for (int i = 0; i < size; i++) {
+            windowSum += numbers.get(i);
+        }
+        sums.add(windowSum);
+
+        for (int i = size; i < numbers.size(); i++) {
+            windowSum += numbers.get(i) - numbers.get(i - size);
+            sums.add(windowSum);
+        }
+
+        return sums;
+    }
