+pub fn match_pattern(pattern: &Pattern, value: &Value) -> Option<Vec<(String, Value)>> {
+    match (pattern, value) {
+        (Pattern::Wildcard, _) => Some(Vec::new()),
+        (Pattern::Literal(expected), Value::Int(actual)) => {
+            if expected == actual {
+                Some(Vec::new())
+            } else {
+                None
+            }
+        }
+        (Pattern::Literal(_), _) => None,
+        (Pattern::Binding(name), _) => Some(vec![(name.clone(), value.clone())]),
+        (Pattern::Tuple(patterns), Value::Tuple(values)) => {
+            if patterns.len() != values.len() {
+                return None;
+            }
+
+            let mut bindings = Vec::new();
+            for (pattern, value) in patterns.iter().zip(values.iter()) {
+                let next = match_pattern(pattern, value)?;
+                bindings = merge_bindings(bindings, next)?;
+            }
+            Some(bindings)
+        }
+        (Pattern::Tuple(_), _) => None,
+        (Pattern::Or(alternatives), _) => {
+            for alternative in alternatives {
+                if let Some(bindings) = match_pattern(alternative, value) {
+                    return Some(bindings);
+                }
+            }
+            None
+        }
+        (Pattern::At(name, inner), _) => {
+            let inner_bindings = match_pattern(inner, value)?;
+            let outer_bindings = vec![(name.clone(), value.clone())];
+            merge_bindings(outer_bindings, inner_bindings)
+        }
+    }
