+    right: Vec<(String, Value)>,
+) -> Option<Vec<(String, Value)>> {
+    for (name, value) in right {
+        if let Some(index) = left.iter().position(|(existing, _)| existing == &name) {
+            if left[index].1 != value {
+                return None;
+            }
+        } else {
+            left.push((name, value));
+        }
+    }
+    Some(left)
+}
