+            .find(|p| p.name == name)
+            .map(|p| p.stock)
+    }
+
+    pub fn insert_coin(&mut self, coin: Coin) -> Result<(), VendingError> {
+        if self.state == State::Dispensing {
+            return Err(VendingError::WrongState);
+        }
+
+        self.credit += coin.value();
+        self.coins.push(coin);
+        self.credit_coins.push(coin);
+        self.state = State::HasCredit;
+        Ok(())
+    }
+
+    pub fn select(&mut self, name: &str) -> Result<Vec<Coin>, VendingError> {
+        if self.state != State::HasCredit {
+            return Err(VendingError::WrongState);
+        }
+
+        let index = self
+            .products
+            .iter()
+            .position(|p| p.name == name)
+            .ok_or(VendingError::UnknownProduct)?;
+
+        if self.products[index].stock == 0 {
+            return Err(VendingError::OutOfStock);
+        }
+
+        let price = self.products[index].price;
+        if self.credit < price {
+            return Err(VendingError::InsufficientFunds);
+        }
+
+        let change_amount = self.credit - price;
+        let change = make_change(&self.coins, change_amount)
+            .ok_or(VendingError::CannotMakeChange)?;
+
+        for coin in &change {
+            if let Some(position) = self.coins.iter().position(|c| c == coin) {
+                self.coins.remove(position);
+            }
+        }
+
+        self.products[index].stock -= 1;
+        self.credit = 0;
+        self.credit_coins.clear();
+        self.pending_product = Some(index);
+        self.state = State::Dispensing;
+        Ok(change)
+    }
+
+    pub fn take_product(&mut self) -> Result<(), VendingError> {
+        if self.state != State::Dispensing {
+            return Err(VendingError::WrongState);
+        }
+
+        if self.pending_product.take().is_none() {
+            return Err(VendingError::WrongState);
+        }
+
+        self.state = State::Idle;
+        Ok(())
+    }
+
+    pub fn refund(&mut self) -> Result<Vec<Coin>, VendingError> {
+        match self.state {
+            State::Dispensing => Err(VendingError::WrongState),
+            State::Idle => Ok(Vec::new()),
+            State::HasCredit => {
+                let refunded = self.credit_coins.clone();
+                for coin in &refunded {
+                    if let Some(position) = self.coins.iter().position(|c| c == coin) {
+                        self.coins.remove(position);
+                    }
+                }
+
+                self.credit = 0;
+                self.credit_coins.clear();
+                self.state = State::Idle;
+                Ok(refunded)
+            }
+        }
+    }
+
+    pub fn restock(&mut self, name: &str, amount: u32) -> Result<(), VendingError> {
+        if self.state == State::Dispensing {
+            return Err(VendingError::WrongState);
+        }
+
+        let product = self
+            .products
+            .iter_mut()
+            .find(|p| p.name == name)
+            .ok_or(VendingError::UnknownProduct)?;
+
+        product.stock += amount;
+        Ok(())
+    }
+}
+
+const DENOMINATIONS: [u32; 4] = [100, 25, 10, 5];
+const COINS: [Coin; 4] = [Coin::Dollar, Coin::Quarter, Coin::Dime, Coin::Nickel];
+
+fn make_change(coins: &[Coin], amount: u32) -> Option<Vec<Coin>> {
+    let mut counts = [0usize; 4];
+
+    for coin in coins {
+        match coin {
+            Coin::Dollar => counts[0] += 1,
+            Coin::Quarter => counts[1] += 1,
+            Coin::Dime => counts[2] += 1,
+            Coin::Nickel => counts[3] += 1,
+        }
+    }
+
+    let mut used = Vec::new();
+    if search_change(0, amount, &mut counts, &mut used) {
+        Some(used)
+    } else {
+        None
+    }
+}
+
+fn search_change(
+    index: usize,
+    remaining: u32,
+    counts: &mut [usize; 4],
+    used: &mut Vec<Coin>,
+) -> bool {
+    if remaining == 0 {
+        return true;
+    }
+
+    if index == DENOMINATIONS.len() {
+        return false;
+    }
+
+    let value = DENOMINATIONS[index];
+    let max = std::cmp::min(counts[index], (remaining / value) as usize);
+
+    for amount in (0..=max).rev() {
+        counts[index] -= amount;
+        for _ in 0..amount {
+            used.push(COINS[index]);
+        }
+
+        if search_change(index + 1, remaining - amount as u32 * value, counts, used) {
+            return true;
+        }
+
+        for _ in 0..amount {
+            used.pop();
+        }
+        counts[index] += amount;
+    }
+
+    false
+}
