+function gcd(a, b) {
+  let x = Math.abs(a);
+  let y = Math.abs(b);
+  while (y !== 0) {
+    const rest = x % y;
+    x = y;
+    y = rest;
+  }
+  return x;
+}
+
+function normalize(numerator, denominator) {
+  let n = numerator;
+  let d = denominator;
+  if (d < 0) {
+    n = -n;
+    d = -d;
+  }
+  const divisor = gcd(n, d);
+  n /= divisor;
+  d /= divisor;
+  if (n === 0) {
+    return { numerator: 0, denominator: 1 };
+  }
+  return { numerator: n, denominator: d };
