+  if (!ROUNDING_MODES.includes(mode)) {
+    throw new RangeError('unknown rounding mode: ' + mode);
+  }
+}
+
+// Returns { sign, magnitude } such that the rounded value is
+// sign * magnitude / 10 ** places.
+function roundToScaledMagnitude(numerator, denominator, places, mode) {
+  const sign = numerator < 0 ? -1 : 1;
+  const a = Math.abs(numerator);
+  const b = Math.abs(denominator);
