+use std::collections::BTreeMap;
+
+pub fn palindromic_anagrams(text: &str) -> Vec<String> {
+    let mut counts: BTreeMap<char, usize> = BTreeMap::new();
+
+    for byte in text.bytes() {
+        let ch = byte.to_ascii_lowercase() as char;
+        if ch.is_ascii_alphanumeric() {
+            *counts.entry(ch).or_insert(0) += 1;
+        }
+    }
+
+    let total: usize = counts.values().sum();
+    if total == 0 {
+        return Vec::new();
+    }
+
+    let mut center = None;
+    let mut odd_count = 0;
+
+    for (&ch, &count) in &counts {
+        if count % 2 == 1 {
+            odd_count += 1;
+            center = Some(ch);
+            if odd_count > 1 {
+                return Vec::new();
+            }
+        }
+    }
+
+    let half_len = total / 2;
+    let mut half_counts: BTreeMap<char, usize> = counts
+        .iter()
+        .filter_map(|(&ch, &count)| {
+            let half = count / 2;
+            if half == 0 {
+                None
+            } else {
+                Some((ch, half))
+            }
+        })
+        .collect();
+
+    let mut current = String::with_capacity(half_len);
+    let mut halves = Vec::new();
+    build_halves(&mut half_counts, half_len, &mut current, &mut halves);
+
+    let mut result = Vec::with_capacity(halves.len());
+
+    for half in halves {
+        let mut palindrome = String::with_capacity(total);
+        palindrome.push_str(&half);
+
+        if let Some(ch) = center {
+            palindrome.push(ch);
+        }
+
+        palindrome.extend(half.chars().rev());
+        result.push(palindrome);
+    }
+
+    result
+}
+
+fn build_halves(
+    counts: &mut BTreeMap<char, usize>,
+    remaining: usize,
+    current: &mut String,
+    result: &mut Vec<String>,
+) {
+    if remaining == 0 {
+        result.push(current.clone());
+        return;
+    }
+
+    let choices: Vec<char> = counts.keys().copied().collect();
+
+    for ch in choices {
+        let count = *counts.get(&ch).unwrap();
+
+        if count == 0 {
+            continue;
+        }
+
+        *counts.get_mut(&ch).unwrap() = count - 1;
+        current.push(ch);
+        build_halves(counts, remaining - 1, current, result);
+        current.pop();
+        *counts.get_mut(&ch).unwrap() += 1;
