+// Union returns the sorted unique values that occur in a or b.
+func Union(a, b []int) []int {
+	union := make(map[int]struct{}, len(a)+len(b))
+	for _, value := range a {
+		union[value] = struct{}{}
+	}
+	for _, value := range b {
+		union[value] = struct{}{}
+	}
+	return sortedKeys(union)
+}
+
+// Intersection returns the sorted unique values that occur in both a and b.
+func Intersection(a, b []int) []int {
+	setB := toSet(b)
+	intersection := make(map[int]struct{})
+	for _, value := range a {
+		if _, ok := setB[value]; ok {
+			intersection[value] = struct{}{}
+		}
+	}
