+package shellsplit
+
+import "errors"
+
+func SplitCommand(input string) ([]string, error) {
+	fields := []string{}
+	var current []byte
+	started := false
+	inSingle := false
+	inDouble := false
+
+	for i := 0; i < len(input); i++ {
+		c := input[i]
+
+		if inSingle {
+			if c == '\'' {
+				inSingle = false
+			} else {
+				current = append(current, c)
+				started = true
+			}
+			continue
+		}
+
+		if inDouble {
+			if c == '\\' {
+				if i+1 >= len(input) {
+					return nil, errors.New("trailing backslash")
+				}
+				i++
+				current = append(current, input[i])
+				started = true
+				continue
+			}
+			if c == '"' {
+				inDouble = false
+				continue
+			}
+			current = append(current, c)
+			started = true
+			continue
+		}
+
+		if isWhitespace(c) {
+			if started {
+				fields = append(fields, string(current))
+				current = nil
+				started = false
+			}
+			continue
+		}
+
+		switch c {
+		case '\\':
+			if i+1 >= len(input) {
+				return nil, errors.New("trailing backslash")
+			}
+			i++
+			current = append(current, input[i])
+			started = true
+		case '\'':
+			inSingle = true
+			started = true
+		case '"':
+			inDouble = true
+			started = true
+		default:
+			current = append(current, c)
+			started = true
+		}
+	}
+
+	if inSingle {
+		return nil, errors.New("unterminated single quote")
+	}
+	if inDouble {
+		return nil, errors.New("unterminated double quote")
+	}
+
+	if started {
+		fields = append(fields, string(current))
+	}
+
+	return fields, nil
+}
+
+func isWhitespace(c byte) bool {
+	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
+}
