+    match command {
+        'L' | 'R' | 'P' | 'D' => {
+            if rest.is_empty() {
+                Ok((command, None))
+            } else {
+                Err(Error::InvalidArgument(command))
+            }
+        }
+        'F' | 'B' | 'W' => {
+            if rest.is_empty() {
+                return Err(Error::MissingArgument(command));
+            }
+            if !rest.chars().all(|c| c.is_ascii_digit()) {
+                return Err(Error::InvalidArgument(command));
+            }
+            let amount: u32 = rest
+                .parse()
+                .map_err(|_| Error::InvalidArgument(command))?;
+            if amount == 0 {
+                Err(Error::InvalidArgument(command))
+            } else {
+                Ok((command, Some(amount)))
+            }
+        }
+        other => Err(Error::UnknownCommand(other)),
+    }
+}
