+fn carried_weight(world: &World, carried: &[u32]) -> u64 {
+    carried
+        .iter()
+        .map(|id| {
+            world
+                .packages
+                .iter()
+                .find(|package| package.id == *id)
+                .map(|package| package.weight as u64)
+                .unwrap_or(0)
+        })
+        .sum()
+}
