+fn move_robot(
+    world: &World,
+    state: &mut State,
+    steps: u32,
+    forward: bool,
+) -> Result<(), Error> {
+    if state.battery < steps {
+        return Err(Error::InsufficientBattery {
+            required: steps,
+            available: state.battery,
+        });
+    }
+
+    let (dx, dy) = state.direction.delta();
+    let sign = if forward { 1 } else { -1 };
+    let mut next = state.position;
+
+    for _ in 0..steps {
+        next.x += dx * sign;
+        next.y += dy * sign;
+
+        if !in_bounds(next, world) {
+            return Err(Error::Wall);
+        }
+        if world.obstacles.contains(&next) {
+            return Err(Error::Obstacle);
+        }
+    }
+
+    state.position = next;
+    state.battery -= steps;
+    Ok(())
+}
+
+pub fn simulate(world: &World, robot: Robot, commands: &str) -> Result<Report, Error> {
+    validate_world(world)?;
+    validate_start(world, &robot)?;
+
+    let mut state = State {
+        position: robot.position,
+        direction: robot.direction,
+        battery: robot.battery,
+        battery_capacity: robot.battery_capacity,
+        capacity: robot.capacity,
+        carried: Vec::new(),
+        delivered: Vec::new(),
+    };
+
+    for token in commands.split_whitespace() {
+        let (command, argument) = parse_token(token)?;
+
+        match command {
+            'F' => {
+                move_robot(world, &mut state, argument.unwrap(), true)?;
+            }
+            'B' => {
+                move_robot(world, &mut state, argument.unwrap(), false)?;
+            }
+            'L' => {
+                state.direction = state.direction.left();
+            }
+            'R' => {
+                state.direction = state.direction.right();
+            }
+            'W' => {
+                let ticks = argument.unwrap();
+                state.battery = state
+                    .battery
+                    .saturating_add(ticks)
+                    .min(state.battery_capacity);
+            }
+            'P' => {
+                let mut chosen: Option<&Package> = None;
+                for package in &world.packages {
+                    if package.position == state.position
+                        && !state.carried.contains(&package.id)
+                        && !state.delivered.contains(&package.id)
+                    {
+                        if chosen.map_or(true, |current| package.id < current.id) {
+                            chosen = Some(package);
+                        }
+                    }
+                }
+
+                let package = chosen.ok_or(Error::NoPackageHere)?;
+                let current_weight = carried_weight(world, &state.carried);
+                if current_weight + package.weight as u64 > state.capacity as u64 {
+                    return Err(Error::CapacityExceeded);
+                }
+                state.carried.push(package.id);
+            }
+            'D' => {
+                if state.carried.is_empty() {
+                    return Err(Error::NothingToDrop);
+                }
+                state.delivered.append(&mut state.carried);
+            }
+            _ => unreachable!(),
+        }
+    }
+
+    Ok(Report {
+        position: state.position,
+        direction: state.direction,
+        battery: state.battery,
+        carried: state.carried,
+        delivered: state.delivered,
+    })
+}
