+// Normalized, de-duplicated, sorted list of the tags on one item.
+std::vector<std::string> distinct_tags(const std::string& item) {
+    std::vector<std::string> tags;
+
+    std::size_t start = 0;
+    while (start <= item.size()) {
+        const std::size_t comma = item.find(',', start);
+        const std::string raw = (comma == std::string::npos)
+                                    ? item.substr(start)
+                                    : item.substr(start, comma - start);
+        const std::string tag = to_lower(trim(raw));
+
+        if (!tag.empty() &&
+            std::find(tags.begin(), tags.end(), tag) == tags.end()) {
+            tags.push_back(tag);
+        }
+
+        if (comma == std::string::npos) {
+            break;
+        }
+        start = comma + 1;
+    }
+
+    std::sort(tags.begin(), tags.end());
+    return tags;
+}
