+    std::sort(report.begin(), report.end(),
+              [](const std::pair<std::string, int>& lhs,
+                 const std::pair<std::string, int>& rhs) {
+                  if (lhs.second != rhs.second) {
+                      return lhs.second > rhs.second;
+                  }
+                  return lhs.first < rhs.first;
+              });
