+    int o_count = 0;
+    for (char cell : board) {
+        if (cell == 'X') {
+            ++x_count;
+        } else if (cell == 'O') {
+            ++o_count;
+        } else if (cell != '.') {
+            throw std::invalid_argument("board may contain only X, O, and .");
