+function extendedGcd(a, b) {
+  let oldR = a;
+  let r = b;
+  let oldS = 1n;
+  let s = 0n;
+
+  while (r !== 0n) {
+    const q = oldR / r;
+
+    const nextR = oldR - q * r;
+    oldR = r;
+    r = nextR;
+
+    const nextS = oldS - q * s;
+    oldS = s;
+    s = nextS;
+  }
