+
+impl Graph {
+    pub fn new() -> Self {
+        Graph {
+            adjacency: HashMap::new(),
+        }
+    }
+
+    pub fn add_node(&mut self, node: &str) {
+        self.adjacency.entry(node.to_string()).or_default();
+    }
+
+    pub fn add_edge(&mut self, from: &str, to: &str, weight: u32) {
+        self.adjacency
+            .entry(from.to_string())
+            .or_default()
+            .insert(to.to_string(), weight);
+        self.adjacency.entry(to.to_string()).or_default();
+    }
+
+    pub fn neighbors(&self, node: &str) -> Vec<(String, u32)> {
+        match self.adjacency.get(node) {
+            Some(edges) => edges
+                .iter()
+                .map(|(neighbor, weight)| (neighbor.clone(), *weight))
+                .collect(),
+            None => Vec::new(),
+        }
+    }
+
+    pub fn node_count(&self) -> usize {
+        self.adjacency.len()
+    }
+
+    pub fn edge_count(&self) -> usize {
+        self.adjacency.values().map(|edges| edges.len()).sum()
+    }
+
+    pub fn shortest_path(
+        &self,
+        start: &str,
+        end: &str,
+    ) -> Result<Option<(u32, Vec<String>)>, GraphError> {
+        if !self.adjacency.contains_key(start) {
+            return Err(GraphError::UnknownStart(start.to_string()));
+        }
+
+        if !self.adjacency.contains_key(end) {
+            return Err(GraphError::UnknownEnd(end.to_string()));
+        }
+
+        if start == end {
+            return Ok(Some((0, vec![start.to_string()])));
+        }
+
+        let mut heap = BinaryHeap::new();
+        let mut best: HashMap<String, (u32, Vec<String>)> = HashMap::new();
+
+        let start_path = vec![start.to_string()];
+        best.insert(start.to_string(), (0, start_path.clone()));
+        heap.push(State {
+            cost: 0,
+            path: start_path,
+        });
+
+        while let Some(State { cost, path }) = heap.pop() {
+            let node = path.last().expect("path is never empty").clone();
+
+            if node == end {
+                return Ok(Some((cost, path)));
+            }
+
+            if let Some((best_cost, best_path)) = best.get(&node) {
+                if *best_cost < cost
+                    || (*best_cost == cost && best_path.as_slice() < path.as_slice())
+                {
+                    continue;
+                }
+            }
+
+            if let Some(edges) = self.adjacency.get(&node) {
+                for (next, weight) in edges {
+                    let next_cost = cost + *weight;
+                    let mut next_path = path.clone();
+                    next_path.push(next.clone());
+
+                    let is_better = match best.get(next) {
+                        None => true,
+                        Some((best_cost, best_path)) => {
+                            next_cost < *best_cost
+                                || (next_cost == *best_cost
+                                    && next_path.as_slice() < best_path.as_slice())
+                        }
+                    };
+
+                    if is_better {
+                        best.insert(next.clone(), (next_cost, next_path.clone()));
+                        heap.push(State {
+                            cost: next_cost,
+                            path: next_path,
+                        });
+                    }
+                }
+            }
+        }
+
+        Ok(None)
+    }
+}
+
+impl Default for Graph {
+    fn default() -> Self {
+        Self::new()
+    }
+}
+
+#[derive(Clone, Eq, PartialEq)]
+struct State {
+    cost: u32,
+    path: Vec<String>,
+}
+
+impl Ord for State {
+    fn cmp(&self, other: &Self) -> Ordering {
+        other
+            .cost
+            .cmp(&self.cost)
+            .then_with(|| other.path.cmp(&self.path))
+    }
+}
+
+impl PartialOrd for State {
+    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
+        Some(self.cmp(other))
+    }
