+#[derive(Debug, Default)]
+pub struct MinMaxQueue {
+    input: Vec<Entry>,
+    output: Vec<Entry>,
+}
+
+#[derive(Debug, Clone, Copy)]
+struct Entry {
+    value: i64,
+    min: i64,
+    max: i64,
+}
+
+impl MinMaxQueue {
+    pub fn new() -> Self {
+        Self::default()
+    }
+
+    pub fn enqueue(&mut self, value: i64) {
+        let (min, max) = match self.input.last() {
+            Some(top) => (value.min(top.min), value.max(top.max)),
+            None => (value, value),
+        };
+
+        self.input.push(Entry { value, min, max });
+    }
+
+    pub fn dequeue(&mut self) -> Option<i64> {
+        self.prepare_output();
+        self.output.pop().map(|entry| entry.value)
+    }
+
+    pub fn peek(&self) -> Option<i64> {
+        if let Some(entry) = self.output.last() {
+            Some(entry.value)
+        } else {
+            self.input.first().map(|entry| entry.value)
+        }
+    }
+
+    pub fn minimum(&self) -> Option<i64> {
+        match (self.output.last(), self.input.last()) {
+            (Some(output), Some(input)) => Some(output.min.min(input.min)),
+            (Some(output), None) => Some(output.min),
+            (None, Some(input)) => Some(input.min),
+            (None, None) => None,
+        }
+    }
+
+    pub fn maximum(&self) -> Option<i64> {
+        match (self.output.last(), self.input.last()) {
+            (Some(output), Some(input)) => Some(output.max.max(input.max)),
+            (Some(output), None) => Some(output.max),
+            (None, Some(input)) => Some(input.max),
+            (None, None) => None,
+        }
+    }
+
+    pub fn len(&self) -> usize {
+        self.output.len() + self.input.len()
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.len() == 0
+    }
+
+    fn prepare_output(&mut self) {
+        if self.output.is_empty() {
+            while let Some(entry) = self.input.pop() {
+                let (min, max) = match self.output.last() {
+                    Some(top) => (entry.value.min(top.min), entry.value.max(top.max)),
+                    None => (entry.value, entry.value),
+                };
+
+                self.output.push(Entry {
+                    value: entry.value,
+                    min,
+                    max,
+                });
+            }
+        }
+    }
