+#include <string>
+#include <utility>
+#include <vector>
+#include <stdexcept>
+
+namespace roman {
+
+std::string to_roman(int value) {
+    if (value < 1 || value > 3999) {
+        throw std::invalid_argument("value must be between 1 and 3999");
+    }
+
+    static const std::vector<std::pair<int, std::string>> table = {
+        {1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"},
+        {100, "C"},  {90, "XC"},  {50, "L"},  {40, "XL"},
+        {10, "X"},   {9, "IX"},   {5, "V"},   {4, "IV"},
+        {1, "I"}
+    };
+
+    std::string result;
+    for (const auto& entry : table) {
+        while (value >= entry.first) {
+            result += entry.second;
+            value -= entry.first;
+        }
+    }
+    return result;
+}
+
+namespace {
+
+int symbol_value(char c) {
+    switch (c) {
+        case 'I': return 1;
+        case 'V': return 5;
+        case 'X': return 10;
+        case 'L': return 50;
+        case 'C': return 100;
+        case 'D': return 500;
+        case 'M': return 1000;
+        default:  throw std::invalid_argument("invalid Roman symbol");
+    }
+}
+
+}  // namespace
+
+int from_roman(const std::string& numeral) {
+    if (numeral.empty()) {
+        throw std::invalid_argument("empty numeral");
+    }
+
+    int total = 0;
+    const std::size_t size = numeral.size();
+    for (std::size_t i = 0; i < size; ++i) {
+        const int current = symbol_value(numeral[i]);
+        const int next = (i + 1 < size) ? symbol_value(numeral[i + 1]) : 0;
+        if (current < next) {
+            total -= current;
+        } else {
+            total += current;
+        }
+    }
+    return total;
+}
+
+}  // namespace roman
