+        }
+
+        return count(denominations, denominations.length - 1, amount, memo);
+    }
+
+    private static long count(int[] denominations, int index, int remaining, long[][] memo) {
+        if (remaining == 0) {
+            return 1L;
+        }
+        if (remaining < 0 || index < 0) {
+            return 0L;
+        }
+        if (memo[index][remaining] != -1L) {
+            return memo[index][remaining];
+        }
+
+        long usingCurrent = count(denominations, index, remaining - denominations[index], memo);
+        long skippingCurrent = count(denominations, index - 1, remaining, memo);
+        memo[index][remaining] = usingCurrent + skippingCurrent;
+        return memo[index][remaining];
+    }
