+std::vector<std::vector<int>> chunk(const std::vector<int>& items, int size) {
+    if (size <= 0) {
+        throw std::invalid_argument("chunk size must be positive");
+    }
+
+    const std::size_t step = static_cast<std::size_t>(size);
+    std::vector<std::vector<int>> chunks;
+
+    for (std::size_t start = 0; start < items.size(); start += step) {
+        std::vector<int> current;
+        for (std::size_t i = start; i < start + step && i < items.size(); ++i) {
+            current.push_back(items[i]);
+        }
+        chunks.push_back(current);
+    }
+
+    return chunks;
