+        match accounts.get_mut(&id) {
+            Some(account) if !account.closed => {
+                if account.balance >= amount {
+                    account.balance -= amount;
+                    Ok(())
+                } else {
+                    Err(Error::InsufficientFunds)
+                }
+            }
+            Some(_) => Err(Error::AccountClosed),
+            None => Err(Error::AccountNotFound),
+        }
+    }
