+        }
+        if (expr instanceof Multiply multiply) {
+            return toPostfix(multiply.left()) + " " + toPostfix(multiply.right()) + " *";
+        }
+        if (expr instanceof Negate negate) {
+            return toPostfix(negate.operand()) + " neg";
