+        }
+        if (expr instanceof Add add) {
+            return 1 + Math.max(depth(add.left()), depth(add.right()));
+        }
+        if (expr instanceof Multiply multiply) {
+            return 1 + Math.max(depth(multiply.left()), depth(multiply.right()));
+        }
+        if (expr instanceof Negate negate) {
+            return 1 + depth(negate.operand());
+        }
+        throw new IllegalArgumentException("Unknown expression: " + expr);
