+// Grid path finder
+//
+// Grid cells:
+//   '.' open floor
+//   '#' wall
+//   'S' start (exactly one per grid)
+//   'E' end (exactly one per grid)
+//
+// Movement is one cell at a time, up/down/left/right. Diagonals are not allowed.
+
+const DIRECTIONS = [
+  [-1, 0],
+  [1, 0],
+  [0, -1],
+  [0, 1],
+];
+
+const INVALID_GRID_MESSAGE =
+  'Grid must contain exactly one start (S) and exactly one end (E)';
+
+function keyOf(row, col) {
+  return `${row},${col}`;
+}
+
+function locateEndpoints(grid) {
+  let start = null;
+  let end = null;
+
+  for (let row = 0; row < grid.length; row += 1) {
+    const line = grid[row];
+    for (let col = 0; col < line.length; col += 1) {
+      const cell = line[col];
+      if (cell === 'S') {
+        if (start !== null) {
+          throw new Error(INVALID_GRID_MESSAGE);
+        }
+        start = [row, col];
+      } else if (cell === 'E') {
+        if (end !== null) {
+          throw new Error(INVALID_GRID_MESSAGE);
+        }
+        end = [row, col];
+      }
+    }
+  }
+
+  if (start === null || end === null) {
+    throw new Error(INVALID_GRID_MESSAGE);
+  }
+
+  return { start, end };
+}
+
+function isWalkable(grid, row, col) {
+  if (row < 0 || row >= grid.length) {
+    return false;
+  }
+  const line = grid[row];
+  if (col < 0 || col >= line.length) {
+    return false;
+  }
+  return line[col] !== '#';
+}
+
+function buildShortestPath(grid) {
+  const { start, end } = locateEndpoints(grid);
+
+  const startKey = keyOf(start[0], start[1]);
+  const queue = [start];
+  const visited = new Set([startKey]);
+  const cameFrom = new Map([[startKey, null]]);
+  let head = 0;
+
+  while (head < queue.length) {
+    const [row, col] = queue[head];
+    head += 1;
+
+    if (row === end[0] && col === end[1]) {
+      const path = [];
+      let current = keyOf(row, col);
+      while (current !== null) {
+        const [pathRow, pathCol] = current.split(',').map(Number);
+        path.push([pathRow, pathCol]);
+        current = cameFrom.get(current);
+      }
+      return path.reverse();
+    }
