+func Parse(s string) (Fraction, error) {
+	if s == "" {
+		return Fraction{}, fmt.Errorf("fractions: empty input")
+	}
+
+	parts := strings.Split(s, "/")
+	if len(parts) > 2 {
+		return Fraction{}, fmt.Errorf("fractions: too many slashes")
+	}
+	if parts[0] == "" {
+		return Fraction{}, fmt.Errorf("fractions: empty numerator")
+	}
+
+	num, ok := new(big.Int).SetString(parts[0], 10)
+	if !ok {
+		return Fraction{}, fmt.Errorf("fractions: invalid numerator")
+	}
+
+	den := big.NewInt(1)
+	if len(parts) == 2 {
+		if parts[1] == "" {
+			return Fraction{}, fmt.Errorf("fractions: empty denominator")
+		}
+		var okDen bool
+		den, okDen = new(big.Int).SetString(parts[1], 10)
+		if !okDen {
