+	switch mode {
+	case RoundDown:
+		if sign < 0 {
+			q.Sub(q, one)
+		}
+	case RoundUp:
+		if sign > 0 {
+			q.Add(q, one)
+		}
+	case RoundTowardZero:
+	case RoundAwayFromZero:
+		roundAway()
+	case RoundHalfAwayFromZero, RoundHalfToEven:
+		twiceAbsR := new(big.Int).Abs(r)
+		twiceAbsR.Lsh(twiceAbsR, 1)
