+            if (nd < res.dist[nu]) {
+                res.dist[nu] = nd;
+                res.ways[nu] = res.ways[iu];
+                res.parent[nu] = idx;
+                pending.push(Item{nd, nidx});
+            } else if (nd == res.dist[nu]) {
+                res.ways[nu] += res.ways[iu];
