+    const Search res = search(start, end);
+    const int s = index_of(start);
+    int idx = index_of(end);
+    if (res.dist[static_cast<std::size_t>(idx)] == kInfinity) {
+        return {};
+    }
+
+    std::vector<Cell> path;
+    while (true) {
+        path.push_back(Cell{idx / cols_, idx % cols_});
+        if (idx == s) {
+            break;
+        }
+        idx = res.parent[static_cast<std::size_t>(idx)];
+    }
+
+    std::reverse(path.begin(), path.end());
+    return path;
+}
+
+unsigned long long GridPathFinder::count_cheapest_paths(Cell start, Cell end) const {
+    check_bounds(start);
+    check_bounds(end);
+    if (!walkable(start) || !walkable(end)) {
+        return 0ULL;
+    }
+
+    const Search res = search(start, end);
+    const std::size_t t = static_cast<std::size_t>(index_of(end));
+    if (res.dist[t] == kInfinity) {
+        return 0ULL;
+    }
+    return res.ways[t];
+}
