+            this.index = 0;
+        }
+
+        int position() {
+            return index;
+        }
+
+        void skipWhitespace() {
+            while (index < input.length() && isWhitespace(input.charAt(index))) {
+                index++;
+            }
+        }
+
+        char peek() {
+            if (index >= input.length()) {
+                throw new IllegalArgumentException("Unexpected end of input");
+            }
+            return input.charAt(index);
+        }
+
+        char advance() {
+            char c = peek();
+            index++;
+            return c;
+        }
+
+        void expect(char expected) {
+            char actual = advance();
+            if (actual != expected) {
+                throw new IllegalArgumentException("Expected '" + expected + "' at position " + (index - 1));
+            }
+        }
+
+        void ensureEnd() {
+            if (index != input.length()) {
+                throw new IllegalArgumentException("Unexpected trailing content at position " + index);
+            }
+        }
