+        if (grid == null || grid.isEmpty()) {
+            return List.of();
+        }
+
+        int rows = grid.size();
+        int columns = grid.get(0).length();
+
+        Point start = null;
+        Point exit = null;
+        for (int row = 0; row < rows; row++) {
+            String line = grid.get(row);
+            for (int column = 0; column < columns; column++) {
+                char cell = line.charAt(column);
+                if (cell == 'S') {
+                    start = new Point(row, column);
+                } else if (cell == 'E') {
+                    exit = new Point(row, column);
+                }
+            }
+        }
+        if (start == null || exit == null) {
+            return List.of();
+        }
+
+        int[][] previous = new int[rows][columns];
+        for (int[] line : previous) {
+            Arrays.fill(line, -1);
+        }
+        boolean[][] seen = new boolean[rows][columns];
+
+        Deque<Point> queue = new ArrayDeque<>();
+        queue.add(start);
+        seen[start.row()][start.column()] = true;
+
+        while (!queue.isEmpty()) {
+            Point current = queue.poll();
+            if (current.equals(exit)) {
+                break;
+            }
+            for (int[] step : NEIGHBOURS) {
+                int row = current.row() + step[0];
+                int column = current.column() + step[1];
+                if (row < 0 || row >= rows || column < 0 || column >= columns) {
+                    continue;
+                }
+                if (seen[row][column] || grid.get(row).charAt(column) == '#') {
+                    continue;
+                }
+                seen[row][column] = true;
+                previous[row][column] = current.row() * columns + current.column();
+                queue.add(new Point(row, column));
+            }
+        }
