+        }
+        for (const auto& iv : other.intervals_) {
+            result.intervals_.push_back(iv);
+        }
+        result.normalize();
+        return result;
+    }
+
+    IntervalSet intersection(const IntervalSet& other) const {
+        IntervalSet result;
+        std::size_t i = 0;
+        std::size_t j = 0;
+        while (i < intervals_.size() && j < other.intervals_.size()) {
+            const int lo = std::max(intervals_[i].first, other.intervals_[j].first);
+            const int hi = std::min(intervals_[i].second, other.intervals_[j].second);
+            if (lo <= hi) {
+                result.intervals_.push_back({lo, hi});
+            }
+            if (intervals_[i].second < other.intervals_[j].second) {
+                ++i;
+            } else if (intervals_[i].second > other.intervals_[j].second) {
