+            char c = s[pos];
+            if (c == '[') {
+                nodes.push_back(parse_group());
+            } else if (c == 'F' || c == 'B' || c == 'L' || c == 'R') {
+                nodes.push_back(parse_cmd());
+            } else if (std::isdigit(static_cast<unsigned char>(c))) {
+                throw std::invalid_argument("digit found where a command was expected");
+            } else {
