+#[derive(Debug, PartialEq, Eq)]
+pub enum BitFieldError {
+    InvalidWidth,
+    InvalidOffset,
+    OutOfBounds,
+    ValueTooLarge,
+}
+
+fn field_mask(width: u32) -> u32 {
+    if width == 32 {
+        u32::MAX
+    } else {
+        (1u32 << width) - 1
+    }
+}
+
+fn validate_field(offset: u32, width: u32) -> Result<(), BitFieldError> {
+    if width == 0 || width > 32 {
+        return Err(BitFieldError::InvalidWidth);
+    }
+    if offset >= 32 {
+        return Err(BitFieldError::InvalidOffset);
+    }
+    if offset + width > 32 {
+        return Err(BitFieldError::OutOfBounds);
+    }
+    Ok(())
+}
+
+pub fn get_bits(value: u32, offset: u32, width: u32) -> Result<u32, BitFieldError> {
+    validate_field(offset, width)?;
+    Ok((value >> offset) & field_mask(width))
+}
+
+pub fn set_bits(value: u32, offset: u32, width: u32, bits: u32) -> Result<u32, BitFieldError> {
+    validate_field(offset, width)?;
+
+    let mask = field_mask(width);
+    if width < 32 && bits > mask {
+        return Err(BitFieldError::ValueTooLarge);
+    }
+
+    let shifted_mask = mask << offset;
+    Ok((value & !shifted_mask) | ((bits & mask) << offset))
+}
+
+pub fn clear_bits(value: u32, offset: u32, width: u32) -> Result<u32, BitFieldError> {
+    validate_field(offset, width)?;
+    let shifted_mask = field_mask(width) << offset;
+    Ok(value & !shifted_mask)
+}
+
+pub fn sign_extend(value: u32, width: u32) -> Result<i64, BitFieldError> {
+    if width == 0 || width > 32 {
+        return Err(BitFieldError::InvalidWidth);
+    }
+
+    let field = value & field_mask(width);
+    let sign_bit = 1u32 << (width - 1);
+
+    if field & sign_bit != 0 {
+        Ok(field as i64 - (1i64 << width))
+    } else {
+        Ok(field as i64)
+    }
