+function assertInteger(value, name) {
+  if (!Number.isSafeInteger(value)) {
+    throw new RangeError(`${name} must be a safe integer`);
+  }
+}
+
+function isPrime(n) {
+  assertInteger(n, 'n');
+  if (n < 2) return false;
+  if (n % 2 === 0) return n === 2;
+  if (n % 3 === 0) return n === 3;
+
+  for (let divisor = 5; divisor * divisor <= n; divisor += 6) {
+    if (n % divisor === 0 || n % (divisor + 2) === 0) {
+      return false;
+    }
+  }
+
+  return true;
+}
+
+function primesUpTo(limit) {
+  assertInteger(limit, 'limit');
+  if (limit < 2) return [];
+
+  const composite = new Uint8Array(limit + 1);
+  const primes = [];
+
+  for (let value = 2; value <= limit; value += 1) {
+    if (!composite[value]) {
+      primes.push(value);
+      if (value * value <= limit) {
+        for (let multiple = value * value; multiple <= limit; multiple += value) {
+          composite[multiple] = 1;
+        }
+      }
+    }
+  }
+
+  return primes;
+}
+
+function nthPrime(n) {
+  assertInteger(n, 'n');
+  if (n < 1) {
+    throw new RangeError('n must be a positive integer');
+  }
+
+  if (n === 1) return 2;
+
+  let upperBound;
+  if (n < 6) {
+    upperBound = 15;
+  } else {
+    const logN = Math.log(n);
+    upperBound = Math.ceil(n * (logN + Math.log(logN))) + 10;
+  }
+
+  while (true) {
+    const primes = primesUpTo(upperBound);
+    if (primes.length >= n) {
+      return primes[n - 1];
+    }
+    upperBound *= 2;
+  }
+}
+
+function primeFactors(n) {
+  assertInteger(n, 'n');
+  if (n < 2) {
+    throw new RangeError('n must be an integer at least 2');
+  }
+
+  const factors = [];
+  let remaining = n;
+
+  while (remaining % 2 === 0) {
+    factors.push(2);
+    remaining /= 2;
+  }
+
+  for (let factor = 3; factor * factor <= remaining; factor += 2) {
+    while (remaining % factor === 0) {
+      factors.push(factor);
+      remaining /= factor;
+    }
+  }
+
+  if (remaining > 1) {
+    factors.push(remaining);
+  }
+
+  return factors;
+}
