+func DayOfYear(date Date) (int, error) {
+	if err := validateDate(date); err != nil {
+		return 0, err
+	}
+
+	total := 0
+	for month := 1; month < date.Month; month++ {
+		days, err := DaysInMonth(date.Year, month)
+		if err != nil {
+			return 0, err
+		}
+		total += days
+	}
+	return total + date.Day, nil
+}
+
+func Weekday(date Date) (time.Weekday, error) {
+	if err := validateDate(date); err != nil {
+		return time.Sunday, err
+	}
+
+	t := time.Date(date.Year, time.Month(date.Month), date.Day, 0, 0, 0, 0, time.UTC)
+	return t.Weekday(), nil
+}
+
+func AddDays(date Date, days int) (Date, error) {
+	if err := validateDate(date); err != nil {
+		return Date{}, err
+	}
+
+	t := time.Date(date.Year, time.Month(date.Month), date.Day, 0, 0, 0, 0, time.UTC)
