+pub fn min_cost_to_merge_stones(stones: &[u32], k: u32) -> Option<u64> {
+    let n = stones.len();
+
+    if n == 0 || k < 2 {
+        return None;
+    }
+
+    if n == 1 {
+        return Some(0);
+    }
+
+    let step = (k - 1) as usize;
+    if (n - 1) % step != 0 {
+        return None;
+    }
+
+    let mut prefix = vec![0u64; n + 1];
+    for (index, &stone) in stones.iter().enumerate() {
+        prefix[index + 1] = prefix[index] + u64::from(stone);
+    }
+
+    let mut dp = vec![vec![0u64; n]; n];
+
+    for len in 2..=n {
+        for start in 0..=n - len {
+            let end = start + len - 1;
+            let mut best = u64::MAX;
+
+            let mut split = start;
+            while split < end {
+                let candidate = dp[start][split].saturating_add(dp[split + 1][end]);
+                if candidate < best {
+                    best = candidate;
+                }
+                split += step;
+            }
+
+            if (len - 1) % step == 0 {
+                best = best.saturating_add(prefix[end + 1] - prefix[start]);
+            }
+
+            dp[start][end] = best;
+        }
+    }
+
+    Some(dp[0][n - 1])
