+    fn literal(&mut self, word: &str) -> Result<(), ParseError> {
+        let end = self.pos + word.len();
+        if end <= self.bytes.len() && &self.bytes[self.pos..end] == word.as_bytes() {
+            self.pos = end;
+            Ok(())
