+        // Caller guarantees the current byte is the opening quote.
+        self.pos += 1;
+        let mut out: Vec<u8> = Vec::new();
+        loop {
+            let c = self.peek().ok_or(ParseError)?;
+            self.pos += 1;
+            match c {
+                b'"' => break,
+                b'\\' => {
+                    let escape = self.peek().ok_or(ParseError)?;
+                    self.pos += 1;
+                    match escape {
+                        b'"' => out.push(b'"'),
+                        b'\\' => out.push(b'\\'),
+                        b'/' => out.push(b'/'),
+                        b'b' => out.push(0x08),
+                        b'f' => out.push(0x0c),
+                        b'n' => out.push(b'\n'),
+                        b'r' => out.push(b'\r'),
+                        b't' => out.push(b'\t'),
+                        _ => return Err(ParseError),
+                    }
+                }
+                _ => out.push(c),
+            }
+        }
