+public class FractionRounding {
+    public static int roundToNearestInt(int numerator, int denominator) {
+        if (denominator == 0) {
+            throw new IllegalArgumentException("denominator must not be zero");
+        }
+
+        long n = numerator;
+        long d = denominator;
+        if (d < 0) {
+            n = -n;
+            d = -d;
+        }
+
+        long absoluteNumerator = Math.abs(n);
+        long quotient = absoluteNumerator / d;
+        long remainder = absoluteNumerator % d;
+
+        if (2 * remainder >= d) {
+            quotient++;
+        }
+
+        return (int) (n < 0 ? -quotient : quotient);
+    }
+}
