+        let left_part = left_parts.next();
+        let right_part = right_parts.next();
+
+        if left_part.is_none() && right_part.is_none() {
+            return Ordering::Equal;
+        }
+
+        let left_part = left_part.unwrap_or("0");
+        let right_part = right_part.unwrap_or("0");
+
+        let ordering = compare_numeric(left_part, right_part);
+        if ordering != Ordering::Equal {
+            return ordering;
+        }
+    }
+}
+
+fn compare_prerelease(left: Option<&str>, right: Option<&str>) -> Ordering {
+    match (left, right) {
+        (None, None) => Ordering::Equal,
+        (None, Some(_)) => Ordering::Greater,
+        (Some(_), None) => Ordering::Less,
+        (Some(left), Some(right)) => compare_prerelease_strings(left, right),
+    }
+}
+
+fn compare_prerelease_strings(left: &str, right: &str) -> Ordering {
+    let mut left_parts = left.split('.');
+    let mut right_parts = right.split('.');
+
+    loop {
+        match (left_parts.next(), right_parts.next()) {
+            (None, None) => return Ordering::Equal,
+            (None, Some(_)) => return Ordering::Less,
+            (Some(_), None) => return Ordering::Greater,
+            (Some(left), Some(right)) => {
+                let ordering = compare_prerelease_identifier(left, right);
+                if ordering != Ordering::Equal {
+                    return ordering;
+                }
+            }
+        }
+    }
+}
+
+fn compare_prerelease_identifier(left: &str, right: &str) -> Ordering {
+    let left_is_numeric = left.chars().all(|c| c.is_ascii_digit());
+    let right_is_numeric = right.chars().all(|c| c.is_ascii_digit());
+
+    match (left_is_numeric, right_is_numeric) {
+        (true, true) => compare_numeric(left, right),
+        (true, false) => Ordering::Less,
+        (false, true) => Ordering::Greater,
+        (false, false) => left.cmp(right),
+    }
+}
+
+fn compare_numeric(left: &str, right: &str) -> Ordering {
+    let left = trim_leading_zeros(left);
+    let right = trim_leading_zeros(right);
+
+    match left.len().cmp(&right.len()) {
+        Ordering::Equal => left.cmp(right),
+        ordering => ordering,
+    }
+}
+
+fn trim_leading_zeros(value: &str) -> &str {
+    let trimmed = value.trim_start_matches('0');
+    if trimmed.is_empty() {
+        "0"
+    } else {
+        trimmed
+    }
+}
