+#include <string>
+#include <vector>
+
+namespace rail_fence_cipher {
+
+static std::vector<int> build_pattern(std::size_t n, int rails) {
+    std::vector<int> pattern(n);
+    int row = 0;
+    int dir = 1;
+    for (std::size_t i = 0; i < n; ++i) {
+        pattern[i] = row;
+        if (rails == 1) continue;
+        if (row == 0) {
+            dir = 1;
+        } else if (row == rails - 1) {
+            dir = -1;
+        }
+        row += dir;
+    }
+    return pattern;
+}
+
+std::string encode(const std::string& text, int rails) {
+    if (rails <= 1 || static_cast<std::size_t>(rails) >= text.size()) {
+        return text;
+    }
+
+    std::vector<std::string> rows(rails);
+    int row = 0;
+    int dir = 1;
+    for (char c : text) {
+        rows[row].push_back(c);
+        if (row == 0) {
+            dir = 1;
+        } else if (row == rails - 1) {
+            dir = -1;
+        }
+        row += dir;
+    }
+
+    std::string result;
+    result.reserve(text.size());
+    for (const auto& r : rows) {
+        result += r;
+    }
+    return result;
+}
+
+std::string decode(const std::string& text, int rails) {
+    if (rails <= 1 || static_cast<std::size_t>(rails) >= text.size()) {
+        return text;
+    }
+
+    std::vector<int> pattern = build_pattern(text.size(), rails);
+    std::vector<std::size_t> counts(rails, 0);
+    for (int r : pattern) {
+        counts[r]++;
+    }
+
+    std::vector<std::string> rows(rails);
+    std::size_t idx = 0;
+    for (int r = 0; r < rails; ++r) {
+        rows[r] = text.substr(idx, counts[r]);
+        idx += counts[r];
+    }
+
+    std::vector<std::size_t> pos(rails, 0);
+    std::string result;
+    result.reserve(text.size());
+    for (int r : pattern) {
+        result.push_back(rows[r][pos[r]++]);
+    }
+    return result;
+}
+
+}
