+                while i < chars.len()
+                    && (chars[i].is_ascii_alphanumeric() || chars[i] == '_')
+                {
+                    i += 1;
+                }
+                let text: String = chars[start..i].iter().collect();
+                tokens.push(Token::Ident(text));
+            }
+            other => {
+                return Err(TokenizeError::UnexpectedChar {
+                    ch: other,
+                    index: i,
+                })
+            }
+        }
+    }
+
+    Ok(tokens)
+}
