+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+pub enum ParseError {
+    UnterminatedSingleQuote,
+    UnterminatedDoubleQuote,
+    TrailingBackslash,
+}
+
+#[derive(Clone, Copy, PartialEq)]
+enum Mode {
+    Normal,
+    Single,
+    Double,
+}
+
+pub fn split_words(input: &str) -> Result<Vec<String>, ParseError> {
+    let chars: Vec<char> = input.chars().collect();
+    let mut words: Vec<String> = Vec::new();
+    let mut current = String::new();
+    let mut word_started = false;
+    let mut mode = Mode::Normal;
+    let mut index = 0;
+
+    while index < chars.len() {
+        let ch = chars[index];
+
+        match mode {
+            Mode::Normal => match ch {
+                '\'' => {
+                    word_started = true;
+                    mode = Mode::Single;
+                    index += 1;
+                }
+                '"' => {
+                    word_started = true;
+                    mode = Mode::Double;
+                    index += 1;
+                }
+                '\\' => {
+                    if index + 1 >= chars.len() {
+                        return Err(ParseError::TrailingBackslash);
+                    }
+                    word_started = true;
+                    current.push(chars[index + 1]);
+                    index += 2;
+                }
+                c if c.is_whitespace() => {
+                    if word_started {
+                        words.push(std::mem::take(&mut current));
+                        word_started = false;
+                    }
+                    index += 1;
+                }
+                c => {
+                    word_started = true;
+                    current.push(c);
+                    index += 1;
+                }
+            },
+            Mode::Single => match ch {
+                '\'' => {
+                    mode = Mode::Normal;
+                    index += 1;
+                }
+                c => {
+                    current.push(c);
+                    index += 1;
+                }
+            },
+            Mode::Double => match ch {
+                '"' => {
+                    mode = Mode::Normal;
+                    index += 1;
+                }
+                '\\' => {
+                    if index + 1 >= chars.len() {
+                        return Err(ParseError::TrailingBackslash);
+                    }
+                    let escaped = chars[index + 1];
+                    match escaped {
+                        '"' | '\\' => current.push(escaped),
+                        other => {
+                            current.push('\\');
+                            current.push(other);
+                        }
+                    }
+                    index += 2;
+                }
+                c => {
+                    current.push(c);
+                    index += 1;
+                }
+            },
+        }
+    }
+
+    match mode {
+        Mode::Single => Err(ParseError::UnterminatedSingleQuote),
+        Mode::Double => Err(ParseError::UnterminatedDoubleQuote),
+        Mode::Normal => {
+            if word_started {
+                words.push(current);
+            }
+            Ok(words)
+        }
+    }
