+class MinMaxQueue {
+private:
+    struct Entry {
+        int value;
+        int min;
+        int max;
+    };
+
+    std::stack<Entry> in_stack;
+    std::stack<Entry> out_stack;
+    std::size_t count = 0;
+
+    static Entry make_entry(int value, const std::stack<Entry>& stack) {
+        if (stack.empty()) {
+            return Entry{value, value, value};
+        }
+        return Entry{
+            value,
+            std::min(value, stack.top().min),
+            std::max(value, stack.top().max)
+        };
+    }
+
+    void transfer_to_out() {
+        while (!in_stack.empty()) {
+            Entry entry = in_stack.top();
+            in_stack.pop();
+            out_stack.push(make_entry(entry.value, out_stack));
+        }
+    }
