+            throw std::out_of_range("dequeue from empty MinMaxQueue");
+        }
+        if (out_stack.empty()) {
+            transfer_to_out();
+        }
+        int value = out_stack.top().value;
+        out_stack.pop();
+        --count;
+        return value;
+    }
