+        if (empty()) {
+            throw std::out_of_range("front of empty MinMaxQueue");
+        }
+        if (!out_stack.empty()) {
+            return out_stack.top().value;
+        }
+        auto copy = in_stack;
+        while (copy.size() > 1) {
+            copy.pop();
+        }
+        return copy.top().value;
+    }
+
+    int back() const {
+        if (empty()) {
+            throw std::out_of_range("back of empty MinMaxQueue");
+        }
+        if (!in_stack.empty()) {
+            return in_stack.top().value;
+        }
+        auto copy = out_stack;
+        while (copy.size() > 1) {
+            copy.pop();
+        }
+        return copy.top().value;
+    }
+
+    int minimum() const {
+        if (empty()) {
+            throw std::out_of_range("minimum of empty MinMaxQueue");
+        }
+        if (in_stack.empty()) {
+            return out_stack.top().min;
+        }
+        if (out_stack.empty()) {
+            return in_stack.top().min;
+        }
+        return std::min(in_stack.top().min, out_stack.top().min);
+    }
+
