+public class PrimeGapAnalyzer {
+    public boolean isPrime(int number) {
+        if (number < 2) {
+            return false;
+        }
+        if (number % 2 == 0) {
+            return number == 2;
+        }
+        for (int divisor = 3; divisor <= number / divisor; divisor += 2) {
+            if (number % divisor == 0) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    public int[] largestPrimeGap(int lower, int upper) {
+        if (lower > upper) {
+            throw new IllegalArgumentException("lower must not exceed upper");
+        }
+
+        int previousPrime = -1;
+        int bestStart = -1;
+        int bestEnd = -1;
+        int bestGap = -1;
+
+        int start = Math.max(lower, 2);
+        for (int value = start; value <= upper; value++) {
+            if (isPrime(value)) {
+                if (previousPrime != -1) {
+                    int gap = value - previousPrime;
+                    if (gap > bestGap) {
+                        bestGap = gap;
+                        bestStart = previousPrime;
+                        bestEnd = value;
+                    }
+                }
+                previousPrime = value;
+            }
+            if (value == Integer.MAX_VALUE) {
+                break;
+            }
+        }
+
+        if (bestStart == -1) {
+            return new int[0];
+        }
+        return new int[]{bestStart, bestEnd};
+    }
+}
