+pub fn illuminated_cells(
+    n: usize,
+    lamps: &[(usize, usize)],
+    queries: &[(usize, usize)],
+) -> Vec<bool> {
+    let mut active: HashSet<(usize, usize)> = lamps.iter().copied().collect();
+
+    let mut rows: HashMap<usize, usize> = HashMap::new();
+    let mut cols: HashMap<usize, usize> = HashMap::new();
+    let mut diag: HashMap<isize, usize> = HashMap::new();
+    let mut anti: HashMap<usize, usize> = HashMap::new();
