+    for &(r, c) in &active {
+        *rows.entry(r).or_insert(0) += 1;
+        *cols.entry(c).or_insert(0) += 1;
+        *diag.entry(r as isize - c as isize).or_insert(0) += 1;
+        *anti.entry(r + c).or_insert(0) += 1;
+    }
+
+    let mut result = Vec::with_capacity(queries.len());
+
+    for &(r, c) in queries {
+        let lit = rows.get(&r).copied().unwrap_or(0) > 0
+            || cols.get(&c).copied().unwrap_or(0) > 0
+            || diag.get(&(r as isize - c as isize)).copied().unwrap_or(0) > 0
+            || anti.get(&(r + c)).copied().unwrap_or(0) > 0;
+
+        result.push(lit);
+
+        let r_min = r.saturating_sub(1);
+        let c_min = c.saturating_sub(1);
+        let r_max = (r + 1).min(n.saturating_sub(1));
+        let c_max = (c + 1).min(n.saturating_sub(1));
+
