+            for cc in c_min..=c_max {
+                if active.remove(&(rr, cc)) {
+                    if let Some(v) = rows.get_mut(&rr) {
+                        *v -= 1;
+                    }
+                    if let Some(v) = cols.get_mut(&cc) {
+                        *v -= 1;
+                    }
+                    let d = rr as isize - cc as isize;
+                    if let Some(v) = diag.get_mut(&d) {
+                        *v -= 1;
+                    }
+                    let a = rr + cc;
+                    if let Some(v) = anti.get_mut(&a) {
+                        *v -= 1;
+                    }
+                }
