+pub fn tokenize(input: &str) -> Result<Vec<Token>, TokenizeError> {
+    let chars: Vec<char> = input.chars().collect();
+    let mut i = 0;
+    let mut tokens = Vec::new();
+
+    while i < chars.len() {
+        let c = chars[i];
+
+        if c.is_whitespace() {
+            i += 1;
+            continue;
+        }
+
+        if c == '/' && i + 1 < chars.len() {
+            let next = chars[i + 1];
+
