+#include <algorithm>
+#include <cstddef>
+#include <memory>
+#include <utility>
+#include <vector>
+
+class BinaryTree {
+public:
+    BinaryTree() = default;
+
+    void insert(int value) {
+        if (insert(root_, value)) {
+            ++size_;
+        }
+    }
+
+    bool contains(int value) const {
+        const Node* current = root_.get();
+        while (current != nullptr) {
+            if (value == current->value) {
+                return true;
+            }
+            current = (value < current->value) ? current->left.get() : current->right.get();
+        }
+        return false;
+    }
+
+    bool remove(int value) {
+        if (remove(root_, value)) {
+            --size_;
+            return true;
+        }
+        return false;
+    }
+
+    std::size_t size() const {
+        return size_;
+    }
+
+    int height() const {
+        return height(root_);
+    }
+
+    std::vector<int> in_order() const {
+        std::vector<int> values;
+        values.reserve(size_);
+        in_order(root_, values);
+        return values;
+    }
+
+private:
+    struct Node {
+        int value;
+        std::unique_ptr<Node> left;
+        std::unique_ptr<Node> right;
+
+        explicit Node(int value) : value(value) {}
+    };
+
+    std::unique_ptr<Node> root_;
+    std::size_t size_ = 0;
+
+    static bool insert(std::unique_ptr<Node>& node, int value) {
+        if (!node) {
+            node.reset(new Node(value));
+            return true;
+        }
+        if (value < node->value) {
+            return insert(node->left, value);
+        }
+        if (value > node->value) {
+            return insert(node->right, value);
+        }
+        return false;
+    }
+
+    static bool remove(std::unique_ptr<Node>& node, int value) {
+        if (!node) {
+            return false;
+        }
+        if (value < node->value) {
+            return remove(node->left, value);
+        }
+        if (value > node->value) {
+            return remove(node->right, value);
+        }
+        if (!node->left) {
+            node = std::move(node->right);
+            return true;
+        }
+        if (!node->right) {
+            node = std::move(node->left);
+            return true;
+        }
+        Node* successor = minimum(node->right.get());
+        node->value = successor->value;
+        remove(node->right, successor->value);
+        return true;
+    }
+
+    static Node* minimum(Node* node) {
+        while (node->left) {
+            node = node->left.get();
+        }
+        return node;
+    }
+
+    static int height(const std::unique_ptr<Node>& node) {
+        if (!node) {
+            return -1;
+        }
+        return 1 + std::max(height(node->left), height(node->right));
+    }
+
+    static void in_order(const std::unique_ptr<Node>& node, std::vector<int>& values) {
+        if (!node) {
+            return;
+        }
+        in_order(node->left, values);
+        values.push_back(node->value);
+        in_order(node->right, values);
+    }
+};
