+    std::vector<int> dp(fuel_needed + 1, inf);
+    dp[0] = 0;
+
+    for (int fuel = 1; fuel <= fuel_needed; ++fuel) {
+        for (int pack : pack_sizes) {
+            if (pack <= 0 || pack > fuel) {
+                continue;
+            }
+            if (dp[fuel - pack] != inf) {
+                dp[fuel] = std::min(dp[fuel], dp[fuel - pack] + 1);
+            }
+        }
+    }
+
+    return dp[fuel_needed] == inf ? -1 : dp[fuel_needed];
+}
