+func FreeSlots(dayStart int, dayEnd int, busy []Interval) ([]Interval, error) {
+	if dayStart >= dayEnd {
+		return nil, errors.New("dayStart must be less than dayEnd")
+	}
+
+	clipped := make([]Interval, 0, len(busy))
+	for _, b := range busy {
+		if b.Start >= b.End {
+			return nil, errors.New("busy interval must have Start < End")
+		}
