+import (
+	"container/list"
+	"sync"
+	"time"
+)
+
+type entry[T any] struct {
+	key       string
+	value     T
+	expiresAt time.Time
+}
+
+type call[T any] struct {
+	done       chan struct{}
+	value      T
+	err        error
+	panicked   bool
+	panicValue any
+}
+
+type Cache[T any] struct {
+	mu       sync.Mutex
+	capacity int
+	ttl      time.Duration
+	now      func() time.Time
+	lru      *list.List
+	items    map[string]*list.Element
+	calls    map[string]*call[T]
+}
+
+func New[T any](capacity int, ttl time.Duration) *Cache[T] {
+	return NewWithClock[T](capacity, ttl, time.Now)
+}
+
+func NewWithClock[T any](capacity int, ttl time.Duration, now func() time.Time) *Cache[T] {
+	if capacity < 1 {
+		panic("memoize: capacity must be at least 1")
+	}
+	if now == nil {
+		panic("memoize: clock must not be nil")
+	}
+	return &Cache[T]{
+		capacity: capacity,
+		ttl:      ttl,
+		now:      now,
+		lru:      list.New(),
+		items:    make(map[string]*list.Element),
+		calls:    make(map[string]*call[T]),
+	}
+}
+
+func (c *Cache[T]) Do(key string, compute func() (T, error)) (T, error) {
+	if compute == nil {
+		panic("memoize: nil compute function")
+	}
+
+	c.mu.Lock()
+	now := c.now()
+	if el, ok := c.items[key]; ok {
+		e := el.Value.(*entry[T])
+		if !c.expired(e, now) {
+			c.lru.MoveToFront(el)
+			value := e.value
+			c.mu.Unlock()
+			return value, nil
+		}
+		c.removeElement(el)
+	}
+
+	if pending, ok := c.calls[key]; ok {
+		c.mu.Unlock()
+		<-pending.done
+		if pending.panicked {
+			panic(pending.panicValue)
+		}
+		return pending.value, pending.err
+	}
+
+	pending := &call[T]{done: make(chan struct{})}
+	c.calls[key] = pending
+	c.mu.Unlock()
+
+	var value T
+	var err error
+	completed := false
+	defer func() {
+		if completed {
+			return
+		}
+		panicValue := recover()
+		if panicValue == nil {
+			panicValue = "memoize: compute panicked"
+		}
+
+		c.mu.Lock()
+		pending.panicked = true
+		pending.panicValue = panicValue
+		delete(c.calls, key)
+		close(pending.done)
+		c.mu.Unlock()
+
+		panic(panicValue)
+	}()
+
+	value, err = compute()
+	completed = true
+
+	c.mu.Lock()
+	if err == nil {
+		c.setLocked(key, value, c.now())
+	}
+	pending.value = value
+	pending.err = err
+	delete(c.calls, key)
+	close(pending.done)
+	c.mu.Unlock()
+
+	return value, err
+}
