+func (c *Cache[T]) Get(key string) (T, bool) {
+	var zero T
+
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	el, ok := c.items[key]
+	if !ok {
+		return zero, false
+	}
+
+	e := el.Value.(*entry[T])
+	if c.expired(e, c.now()) {
+		c.removeElement(el)
+		return zero, false
+	}
+
+	c.lru.MoveToFront(el)
+	return e.value, true
+}
+
+func (c *Cache[T]) Set(key string, value T) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	c.setLocked(key, value, c.now())
+}
+
+func (c *Cache[T]) Delete(key string) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	if el, ok := c.items[key]; ok {
+		c.removeElement(el)
+	}
+}
+
+func (c *Cache[T]) Len() int {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	c.pruneExpiredLocked(c.now())
+	return c.lru.Len()
+}
+
+func (c *Cache[T]) expired(e *entry[T], now time.Time) bool {
+	return c.ttl > 0 && !now.Before(e.expiresAt)
+}
+
+func (c *Cache[T]) expiry(now time.Time) time.Time {
+	if c.ttl > 0 {
+		return now.Add(c.ttl)
+	}
+	return time.Time{}
+}
+
+func (c *Cache[T]) setLocked(key string, value T, now time.Time) {
+	c.pruneExpiredLocked(now)
+
