+		e.value = value
+		e.expiresAt = c.expiry(now)
+		c.lru.MoveToFront(el)
+		return
+	}
+
+	e := &entry[T]{
+		key:       key,
+		value:     value,
+		expiresAt: c.expiry(now),
+	}
+	el := c.lru.PushFront(e)
+	c.items[key] = el
+
+	for c.lru.Len() > c.capacity {
+		back := c.lru.Back()
+		if back == nil {
+			break
+		}
+		c.removeElement(back)
+	}
+}
+
